// Recall-mode questions — Behavioral Science (part 2)
// Format: {s: tag, q: stem, choices: [4], ans: 0-3 index into choices, exp: explanation}
const QB_BEHAVIORAL_2 = [
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ are the intended, deliberate consequences of an action or institution that serve to help a given social system',choices:['Latent functions','Manifest functions','Social dysfunctions','Social facts'],ans:1,exp:'In functionalism, **manifest functions** are the intended, recognized purposes of an action or institution (e.g., schools exist to educate). Latent functions are the unintended by-products (e.g., schools also serve as marriage markets).'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ are the unexpected, unintended, or unrecognized consequences of manifest actions',choices:['Manifest functions','Social institutions','Latent functions','Social norms'],ans:2,exp:'**Latent functions** are unintended consequences of an action (e.g., college fostering lifelong friendships). Manifest functions are the deliberate, intended purposes; Merton coined both terms within functionalism.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____, rooted in the work of Karl Marx, claims that society is in a state of perpetual conflict because of competition for limited resources',choices:['Functionalism','Symbolic interactionism','Social constructionism','Conflict theory'],ans:3,exp:'**Conflict theory** (Marx) sees society as groups competing for scarce resources and power, with the dominant group maintaining inequality. Functionalism, by contrast, emphasizes how parts of society work together to maintain stability.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ is the study of the way that distinct groups within society compete for resources and power',choices:['Structural functionalism','Conflict sociology','Symbolic interactionism','Rational choice theory'],ans:1,exp:'**Conflict sociology** is the macro-level study of how groups (classes, genders, races) compete for resources and power. Structural functionalism instead asks how social structures contribute to overall stability.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ is the study of the way individuals interact through a shared understanding of words, gestures, and other symbols',choices:['Symbolic interactionism','Conflict theory','Functionalism','Social exchange theory'],ans:0,exp:'**Symbolic interactionism** (Mead, Blumer) is a micro-level theory: people act toward things based on the meanings symbols carry, and those meanings arise from social interaction. Social exchange theory instead explains interaction as a cost-benefit trade.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ is the study of the small-scale components that make up a society, such as face-to-face interactions, expressions, and symbolic gestures',choices:['Macrosociology','Demography','Microsociology','Functionalism'],ans:2,exp:'**Microsociology** focuses on individuals and small-group interaction (symbolic interactionism is a classic micro approach). Macrosociology studies large-scale structures such as institutions and whole societies.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ explores the ways in which individuals and groups agree upon a shared social reality and the value they place on certain social constructs',choices:['Rational choice theory','Conflict theory','Functionalism','Social constructionism'],ans:3,exp:'**Social constructionism** holds that concepts such as money, gender, or race have meaning only because people collectively agree they do. Rational choice theory instead models individual decisions as cost-benefit calculations.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'The _____ states that individuals will make decisions that maximize benefit and minimize harm',choices:['conflict theory','symbolic interactionism','rational choice theory','feminist theory'],ans:2,exp:'**Rational choice theory** assumes people weigh costs and benefits and choose the option with the greatest net reward; applied to interactions, it becomes social exchange theory. Conflict theory focuses on group competition rather than individual calculation.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ explores the ways in which one gender can be subordinated, whether in society as a whole or in specific institutions',choices:['Functionalism','Symbolic interactionism','Rational choice theory','Feminist theory'],ans:3,exp:'**Feminist theory** examines gender inequality and how social structures privilege one gender over another; it is often grouped with conflict-based approaches. Functionalism instead asks how institutions maintain social stability.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ are well-established social structures, such as family, education, religion, and government, that dictate certain patterns of behavior or relationships',choices:['Primary groups','Social institutions','Social networks','Subcultures'],ans:1,exp:'**Social institutions** (family, education, religion, government, economy, medicine) are durable structures that organize behavior around basic societal needs. A primary group is a small, intimate group such as close friends, not a society-wide structure.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ is defined as the shared beliefs, behaviors, norms, and material objects that characterize a human society',choices:['Culture','Society','Socialization','Ethnocentrism'],ans:0,exp:'**Culture** is the whole way of life a group shares, both material (objects) and symbolic (values, norms, language). Society refers to the group of people who share a culture, not the culture itself.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ refers to the physical objects, resources, and spaces that people use to define their culture',choices:['Symbolic culture','Material culture','Cultural capital','Subculture'],ans:1,exp:'**Material culture** includes tangible artifacts such as buildings, clothing, and tools. Symbolic (non-material) culture is the intangible ideas, values, and language that give those objects meaning.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'Sociologists sometimes refer to non-material culture as _____, because its central component is the symbols that people use',choices:['material culture','popular culture','symbolic culture','counterculture'],ans:2,exp:'**Symbolic culture** comprises the ideas a group shares (values, beliefs, norms, language), all communicated through symbols. Material culture is the physical objects; a counterculture is a group that rejects the dominant culture\'s values.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'The term _____ refers to the notion that culture takes time to catch up with technological innovations',choices:['cultural lag','culture shock','cultural diffusion','cultural relativism'],ans:0,exp:'**Cultural lag** (Ogburn) occurs when material culture, especially technology, changes faster than non-material culture such as laws and norms (e.g., privacy law lagging behind social media). Culture shock is the disorientation a person feels on entering an unfamiliar culture.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'Language is defined as spoken or written _____ combined into a system',choices:['norms','values','rituals','symbols'],ans:3,exp:'Language is a system of **symbols** (words, written characters) with shared meanings, and it is a core part of symbolic culture. Norms and values are other elements of culture that language helps transmit.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'A person\'s _____ is a standard for what they deem important or desirable in life',choices:['norm','value','sanction','belief'],ans:1,exp:'A **value** is a standard of what is important or good (e.g., honesty, family). A belief is what a person considers to be true, and a norm is a shared rule for behavior.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'A person\'s _____ is something they consider to be true',choices:['value','norm','ritual','belief'],ans:3,exp:'A **belief** is a conviction that something is true (e.g., that hard work pays off). A value is a judgment about what is important; beliefs and values together shape norms.'},
  {s:'Emotion, Motivation & Stress',aamc:'9A',q:'A _____ is a formal ceremonial behavior that usually includes symbolism',choices:['folkway','sanction','value','ritual'],ans:3,exp:'A **ritual** is a formal, ceremonial, often symbolic behavior (e.g., weddings, graduations, religious rites). A folkway is an everyday norm about polite behavior with only mild sanctions for violation.'},
  {s:'Social Psychology & Society',aamc:'9B',q:'_____ are characteristics of a population such as race, ethnicity, gender, age, education, occupation, income level, and marital status',choices:['Demographics','Social strata','Ethnographies','Vital rates'],ans:0,exp:'**Demographics** are the statistical characteristics of a population; demography is the study of them. Vital rates such as birth and death rates describe population change, not population characteristics.'},
  {s:'Social Psychology & Society',aamc:'9B',q:'_____ is the average number of children born to a woman during her lifetime in a population',choices:['Crude birth rate','Mortality rate','Population growth rate','Fertility rate'],ans:3,exp:'The (total) **fertility rate** is the average number of children per woman over her lifetime; about 2.1 is replacement level in developed countries. The crude birth rate is instead the number of births per 1,000 people per year.'},
  {s:'Social Psychology & Society',aamc:'9B',q:'_____ is usually measured as the number of births or deaths per 1,000 people per year',choices:['Total fertility rate','Birth and mortality rate','Life expectancy','Incidence'],ans:1,exp:'Crude **birth and mortality rates** are expressed per 1,000 people per year; their difference (plus net migration) gives the population growth rate. The total fertility rate is expressed per woman, not per 1,000 people.'},
  {s:'Social Psychology & Society',aamc:'9B',q:'_____ is the movement of people from one geographic location to another',choices:['Urbanization','Globalization','Migration','Social mobility'],ans:2,exp:'**Migration** is geographic movement, driven by push factors (e.g., war, poverty) and pull factors (e.g., jobs). Social mobility is movement between social strata, which need not involve any change of location.'},
  {s:'Social Psychology & Society',aamc:'9B',q:'The theory of _____ describes how birth and death rates change as a society industrializes, and how this changes its population growth rate',choices:['Malthusian population growth','world systems','demographic transition','modernization'],ans:2,exp:'**Demographic transition** describes a shift from high birth and death rates to low birth and death rates with industrialization; death rates fall first, causing a period of rapid growth. Malthusian theory instead predicts that population growth will outstrip the food supply.'},
  {s:'Social Psychology & Society',aamc:'9B',q:'_____ are organized to either promote (proactive) or resist (reactive) social change',choices:['Social movements','Fads','Mobs','Social institutions'],ans:0,exp:'**Social movements** are organized, sustained efforts to promote (proactive) or resist (reactive) change, such as the civil rights movement. Fads and mobs are short-lived, unorganized forms of collective behavior.'},
  {s:'Social Psychology & Society',aamc:'9B',q:'_____ is the process of integrating a global economy with free trade and the tapping of foreign labor markets',choices:['Urbanization','Globalization','Cultural diffusion','Industrialization'],ans:1,exp:'**Globalization** is the growing worldwide integration of economies and cultures, driven by trade, communication, and transportation. Cultural diffusion is narrower: the spread of a single cultural element from one group to another.'},
  {s:'Social Psychology & Society',aamc:'9B',q:'_____ refers to the population shift from rural areas to urban areas',choices:['Suburbanization','Gentrification','Urbanization','Globalization'],ans:2,exp:'**Urbanization** is the concentration of a population in cities, often driven by industrialization and jobs. Gentrification is the influx of wealthier residents into an existing urban neighborhood, often displacing poorer residents.'},
  {s:'Social Psychology & Society',aamc:'10A',q:'_____ is the system by which society ranks categories of people into a hierarchy',choices:['Social stratification','Social mobility','Social reproduction','Meritocracy'],ans:0,exp:'**Social stratification** ranks people by wealth, power, and prestige into layers (strata). Social mobility is the movement of people between those strata.'},
  {s:'Social Psychology & Society',aamc:'10A',q:'_____ states that social stratification is necessary because it motivates those with special intelligence, knowledge, and skills to fill the most important professions and occupations',choices:['Conflict theory','Symbolic interactionism','Functionalism','Social constructionism'],ans:2,exp:'The **functionalist** Davis-Moore thesis argues that unequal rewards are needed to draw the most talented people into the most important roles. Conflict theory counters that stratification simply preserves the advantages of the powerful.'},
  {s:'Social Psychology & Society',aamc:'10A',q:'_____ is a category of people with shared socioeconomic characteristics',choices:['Caste','Ethnic group','Social class','Reference group'],ans:2,exp:'A **social class** groups people by similar income, education, occupation, and wealth, and allows some mobility. A caste is a closed, ascribed stratum fixed at birth.'},
  {s:'Social Psychology & Society',aamc:'10A',q:'_____ is a term that describes the respect and importance tied to specific occupations or associations',choices:['Power','Social capital','Prestige','Cultural capital'],ans:2,exp:'**Prestige** is the social respect attached to a position (e.g., physicians rank high). Power is the capacity to influence others, and it can exist without prestige.'},
  {s:'Social Psychology & Society',aamc:'10A',q:'_____ is the capacity to influence people',choices:['Power','Prestige','Wealth','Esteem'],ans:0,exp:'**Power** is the ability to influence others or control resources; Weber added that legitimate power is authority. Prestige is respect, which may or may not bring influence.'},
  {s:'Social Psychology & Society',aamc:'7B',q:'_____ is a lack of social norms, or the breakdown of social bonds between individuals and society',choices:['Deviance','Anomie','Stigma','Social exclusion'],ans:1,exp:'**Anomie** (Durkheim) is normlessness: weak social regulation during rapid change, which he linked to deviance and suicide. Deviance is the violation of norms that do exist.'},
  {s:'Social Psychology & Society',aamc:'7B',q:'_____ focuses on how anomic conditions can lead to deviance, and in turn reinforce social stratification',choices:['Labeling theory','Differential association theory','Strain theory','Social control theory'],ans:2,exp:'Merton\'s **strain theory** says deviance results when society promotes goals (e.g., wealth) but blocks the legitimate means to reach them. Differential association theory instead says deviance is learned from close contacts.'},
  {s:'Social Psychology & Society',aamc:'10A',q:'_____ is a term used to describe the benefits provided by social networks, or the investment people make in their society in return for rewards',choices:['Cultural capital','Human capital','Economic capital','Social capital'],ans:3,exp:'**Social capital** is the value of one\'s social network (e.g., getting a job through a contact). Cultural capital (Bourdieu) is non-financial assets such as education, tastes, and manners that confer status.'},
  {s:'Social Psychology & Society',aamc:'10A',q:'Advancement up the social ladder based on intellectual talent and achievement occurs in _____',choices:['a caste system','a meritocracy','a plutocracy','an aristocracy'],ans:1,exp:'In **a meritocracy**, status is achieved through ability and effort rather than ascribed by birth or wealth. A caste system is closed, with status fixed at birth and almost no mobility.'},
  {s:'Social Psychology & Society',aamc:'10A',q:'_____ is the movement of individuals, families, households, or other categories of people within or between social strata in a society',choices:['Social stratification','Migration','Social reproduction','Social mobility'],ans:3,exp:'**Social mobility** can be upward or downward, intergenerational or intragenerational, and horizontal or vertical. Migration is movement between places, not between strata.'},
  {s:'Social Psychology & Society',aamc:'10A',q:'_____ refers to the state in which an individual cannot afford a basic subsistence level; that is, they lack necessities of life such as food, clothing, and shelter',choices:['Absolute poverty','Relative poverty','Social exclusion','Spatial inequality'],ans:0,exp:'**Absolute poverty** is defined by a fixed standard of basic needs, regardless of how others in the society live. Relative poverty is measured against the society\'s average standard of living.'},
  {s:'Social Psychology & Society',aamc:'10A',q:'_____ is the condition in which people lack the minimum income needed to maintain the average standard of living in the society in which they live',choices:['Absolute poverty','Relative deprivation','Relative poverty','Social exclusion'],ans:2,exp:'**Relative poverty** is poverty compared with others in the same society, so it depends on that society\'s standards. Absolute poverty means being unable to meet basic survival needs at all.'},
  {s:'Social Psychology & Society',aamc:'9B',q:'_____ states that people seek to acquire something that others possess and which they believe they should have too',choices:['Strain theory','Relative deprivation theory','Rational choice theory','Social exchange theory'],ans:1,exp:'**Relative deprivation theory** says discontent (and often social movements) arises from feeling deprived compared with others, not from absolute lack. Strain theory instead explains deviance as a gap between cultural goals and legitimate means.'},
  {s:'Social Psychology & Society',aamc:'10A',q:'_____ is the passing on of social inequality, especially poverty, from one generation to the next',choices:['Social mobility','Social stratification','Social reproduction','Social exclusion'],ans:2,exp:'**Social reproduction** describes how structures such as schools and inheritance transmit inequality across generations (Bourdieu emphasized cultural capital). Intergenerational social mobility is the opposite: children ending up in a different stratum from their parents.'},
  {s:'Social Psychology & Society',aamc:'10A',q:'_____ is a sense of powerlessness when individuals feel alienated from society',choices:['Anomie','Social exclusion','Relative deprivation','Social stratification'],ans:1,exp:'**Social exclusion** occurs when people (often those in poverty) are cut off from full participation in society and feel powerless and alienated. Anomie is a society-level lack of norms, not an individual\'s exclusion.'},
  {s:'Social Psychology & Society',aamc:'10A',q:'_____ is social stratification across territories, such as neighborhoods, regions, or nations',choices:['Social reproduction','Relative poverty','Environmental justice','Spatial inequality'],ans:3,exp:'**Spatial inequality** is the unequal distribution of resources and services across places (e.g., urban versus rural, or global North versus South). Environmental justice addresses one specific form: the unequal burden of pollution on poor and minority communities.'},
  {s:'Social Psychology & Society',aamc:'10A',q:'_____ is the number of new cases of a disease per population at risk over a period of time',choices:['Prevalence','Morbidity','Incidence','Mortality'],ans:2,exp:'**Incidence** counts only new cases among those at risk over a time period; it measures risk. Prevalence counts all existing cases (new and old) at a point in time, so chronic diseases have high prevalence relative to incidence.'},
  {s:'Social Psychology & Society',aamc:'10A',q:'_____ is the total number of existing cases of a disease per population at a given time',choices:['Incidence','Morbidity','Mortality','Prevalence'],ans:3,exp:'**Prevalence** includes both new and existing cases (prevalence ≈ incidence × disease duration). Incidence counts only new cases among those at risk.'},
  {s:'Social Psychology & Society',aamc:'10A',q:'_____ is the burden or degree of illness associated with a given disease',choices:['Mortality','Incidence','Prevalence','Morbidity'],ans:3,exp:'**Morbidity** is the illness burden of a disease (e.g., disability or reduced quality of life). Mortality refers to deaths caused by the disease.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'The _____ (2010) attempts to increase health insurance coverage rates and reduce the cost of health care in the United States',choices:['Health Insurance Portability and Accountability Act','Affordable Care Act','Emergency Medical Treatment and Active Labor Act','Genetic Information Nondiscrimination Act'],ans:1,exp:'The **Affordable Care Act** expanded coverage through insurance marketplaces, Medicaid expansion, and a ban on denials for pre-existing conditions. HIPAA (1996) mainly protects the privacy and portability of health information.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ is a federal insurance program covering people 65 years and older, as well as younger people with certain disabilities, end-stage renal disease, or ALS',choices:['Medicaid','Medicare','CHIP','TRICARE'],ans:1,exp:'**Medicare** is federally run and based on age or disability, not income. Mnemonic: Medi**care** is for the elderly you **care** for; Medic**aid** **aid**s those in financial need.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ is a joint federal-state insurance program covering patients in significant financial need',choices:['Medicare','TRICARE','Medicaid','Medigap'],ans:2,exp:'**Medicaid** is means-tested (based on income) and jointly funded by federal and state governments. Medicare is based on age (65 and older) or disability, regardless of income.'},
  {s:'Sensation & Perception',aamc:'6A',q:'_____ of the eyes is the simultaneous inward rotation of both eyes toward each other; proprioceptive feedback from the extraocular muscles is used to judge the _____ of an object',choices:['Convergence / distance','Divergence / brightness','Retinal disparity / color','Convergence / shape'],ans:0,exp:'**Convergence** is a binocular depth cue: the eyes rotate inward more for near objects, and feedback from the extraocular muscles signals the object\'s **distance**. Retinal disparity is a different binocular cue based on the slightly different images on each retina.'},
  {s:'Sensation & Perception',aamc:'6A',q:'_____ provide depth information when viewing a scene with only one eye',choices:['Monocular cues','Binocular cues','Retinal disparity cues','Convergence cues'],ans:0,exp:'**Monocular cues** (relative size, interposition, linear perspective, texture gradient, motion parallax, shading) work with one eye. Retinal disparity and convergence are binocular cues that require both eyes.'},
  {s:'Sensation & Perception',aamc:'6A',q:'_____ is a monocular depth cue in which, as the observer moves, nearby objects appear to move farther and faster across the visual field than distant objects',choices:['Relative size','Motion parallax','Interposition','Linear perspective'],ans:1,exp:'In **motion parallax**, objects close to a moving observer sweep past quickly while distant objects (e.g., mountains seen from a car) seem nearly still. Interposition is a static cue in which a nearer object partially blocks a farther one.'},
  {s:'Sensation & Perception',aamc:'6A',q:'_____ is the tendency to see familiar objects as having a standard shape, size, color, or location regardless of changes in viewing angle, distance, or lighting',choices:['Feature detection','Sensory adaptation','Gestalt closure','Object constancy'],ans:3,exp:'**Object (perceptual) constancy** includes size, shape, and color constancy: a door still looks rectangular when opened at an angle. It is a top-down perceptual process, unlike sensory adaptation, which is a drop in receptor responsiveness to a constant stimulus.'},
  {s:'Sensation & Perception',aamc:'6A',q:'_____ are stimuli that fall below a person\'s threshold for conscious perception',choices:['Supraliminal stimuli','Just-noticeable differences','Subliminal stimuli','Absolute thresholds'],ans:2,exp:'**Subliminal stimuli** are below the absolute threshold for conscious awareness, though they may still have subtle effects (e.g., priming). The just-noticeable difference is the smallest detectable change between two stimuli, which is a different kind of threshold.'},
  {s:'Sensation & Perception',aamc:'6A',q:'If you move your head quickly and then stop suddenly, the _____ continues to move in the semicircular canals, giving a false sense of movement experienced as dizziness',choices:['perilymph','endolymph','otolith membrane','aqueous humor'],ans:1,exp:'The **endolymph** in the membranous semicircular canals lags behind and then keeps moving through inertia, deflecting the hair cells in the cupula and signaling rotation that is no longer happening. Perilymph surrounds the membranous labyrinth and does not drive this signal.'},
  {s:'Sensation & Perception',aamc:'6A',q:'In signal detection theory, a _____ response strategy is one in which the observer says "yes" whenever there may be a signal',choices:['conservative','liberal','neutral','adaptive'],ans:1,exp:'A **liberal** strategy maximizes hits but also produces many false alarms. A conservative strategy says "yes" only when confident, producing more misses and correct rejections.'},
  {s:'Sensation & Perception',aamc:'6A',q:'In signal detection theory, a _____ response strategy is one in which the observer says "yes" only when the signal is almost certain',choices:['liberal','neutral','conservative','adaptive'],ans:2,exp:'A **conservative** strategy minimizes false alarms at the cost of more misses (e.g., a radiologist who calls a tumor only when certain). A liberal strategy accepts more false alarms to maximize hits.'},
  {s:'Sensation & Perception',aamc:'6A',q:'According to the Gestalt principle of symmetry, elements that are symmetrical to each other tend to be perceived as _____',choices:['a set of separate objects','a figure against a background','a single unified group','the continuation of a line'],ans:2,exp:'The **symmetry** principle says the mind groups symmetrical elements into **a single unified group** (e.g., [ ] { } ( ) is seen as three bracketed pairs). Figure-ground organization is a separate principle about separating an object from its background.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The Gestalt law of _____ states that humans perceive visual elements that move at the same speed and/or in the same direction as parts of a single stimulus',choices:['proximity','common fate','similarity','continuity'],ans:1,exp:'**Common fate** groups elements that move together (e.g., a flock of birds). Proximity groups elements that are close together in space, regardless of movement.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The Gestalt law of _____ states that elements tend to be perceived according to an observer\'s prior familiarity with them',choices:['closure','prägnanz','similarity','past experience'],ans:3,exp:'The law of **past experience** says familiar patterns shape grouping (e.g., reading "13" as the letter B in a word context). Prägnanz says we perceive the simplest possible organization of a stimulus.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The _____ is the thin transparent membrane that lines the inner surface of the eyelid and covers the white part of the eye',choices:['cornea','sclera','choroid','conjunctiva'],ans:3,exp:'The **conjunctiva** is a mucous membrane over the sclera and inside the eyelids; inflammation of it is "pink eye" (conjunctivitis). It does not cover the cornea, the clear dome over the iris that does most of the eye\'s refraction.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The _____ is the aqueous humor-filled space inside the eye between the iris and the cornea\'s innermost surface (the endothelium)',choices:['posterior chamber','anterior chamber','vitreous chamber','suprachoroidal space'],ans:1,exp:'The **anterior chamber** lies in front of the iris; aqueous humor made by the ciliary body flows from the posterior chamber through the pupil into it and drains via the canal of Schlemm. Blocked drainage raises intraocular pressure (glaucoma).'},
  {s:'Sensation & Perception',aamc:'6A',q:'The _____ is a part of the eye that includes the ciliary muscle, which controls the shape of the lens, and the ciliary epithelium, which produces the aqueous humor',choices:['ciliary body','iris','choroid','suspensory ligament'],ans:0,exp:'The **ciliary body** both makes aqueous humor and adjusts the lens for accommodation: contraction of the ciliary muscle slackens the zonules so the lens rounds up for near vision. The suspensory ligaments (zonules) only transmit this tension; they contain no muscle.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The _____ is a narrow, aqueous humor-filled space behind the peripheral part of the iris and in front of the suspensory ligament of the lens and the ciliary processes',choices:['anterior chamber','vitreous chamber','posterior chamber','subretinal space'],ans:2,exp:'The **posterior chamber** sits between the iris and the lens, where the ciliary processes secrete aqueous humor. The vitreous chamber, behind the lens, holds gel-like vitreous humor instead.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The _____ is the largest chamber of the eye, located behind the lens and in front of the retina and optic nerve',choices:['anterior chamber','posterior chamber','lens capsule','vitreous chamber'],ans:3,exp:'The **vitreous chamber** holds the vitreous humor, which keeps the eyeball\'s shape and makes up most of its volume. The anterior and posterior chambers, in front of the lens, contain watery aqueous humor.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The _____ is an oval-shaped pigmented area near the center of the retina with a very high concentration of cones; its central pit (the fovea) contains no rods',choices:['optic disc','macula','retinal pigment epithelium','choroid'],ans:1,exp:'The **macula** is the cone-rich central retina responsible for high-acuity central vision; rods thin out toward its center, and the fovea contains only cones. The optic disc is the blind spot, where the optic nerve exits and there are no photoreceptors at all.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The _____ is a tiny pit at the center of the macula that contains only cones and provides the sharpest vision',choices:['macula','optic disc','fovea','ora serrata'],ans:2,exp:'The **fovea** is packed with cones, each with nearly a one-to-one connection to a ganglion cell, which gives maximal acuity. The optic disc, by contrast, has no photoreceptors and forms the blind spot.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The _____ is the vascular layer of the eye, lying between the retina and the sclera, that nourishes the outer layers of the retina',choices:['sclera','choroid','ciliary body','retina'],ans:1,exp:'The **choroid** is a pigmented, blood-vessel-rich layer that supplies the photoreceptors and absorbs stray light. The sclera is the tough outer white coat and is largely avascular.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The _____, also known as the white of the eye, is the opaque, fibrous, protective outer layer of the eye made mainly of collagen with some elastic fiber',choices:['cornea','choroid','sclera','conjunctiva'],ans:2,exp:'The **sclera** is continuous with the cornea at the front of the eye; both form the outer fibrous tunic. The cornea is transparent and refracts light, while the sclera is opaque and protective.'},
  {s:'Sensation & Perception',aamc:'6A',q:'_____ is the process by which light is converted into electrical signals in the rods, cones, and photosensitive ganglion cells of the retina',choices:['Lens accommodation','Visual phototransduction','Retinal dark adaptation','Binocular convergence'],ans:1,exp:'In **visual phototransduction**, light isomerizes 11-cis-retinal, activating transducin and phosphodiesterase; cGMP falls, Na⁺ channels close, and the photoreceptor hyperpolarizes. Accommodation is the change in lens shape for focusing and does not convert light into neural signals.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The _____ system of vision is mediated by cones and operates at high light levels',choices:['photopic','scotopic','mesopic','binocular'],ans:0,exp:'**Photopic** vision (daylight) relies on cones, giving color vision and high acuity. Scotopic vision (dim light) relies on rods and is colorless and low in acuity.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The _____ system of vision is mediated by rods and operates at very low light levels',choices:['photopic','mesopic','scotopic','binocular'],ans:2,exp:'**Scotopic** vision relies on the highly sensitive rods, so night vision is grayscale and blurry; looking slightly off-center at a dim star uses rod-rich peripheral retina. Photopic vision uses cones in bright light.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The _____ system of vision involves both rods and cones and operates at moderately low light levels, such as at dusk',choices:['photopic','mesopic','scotopic','binocular'],ans:1,exp:'**Mesopic** vision is the intermediate range in which rods and cones are both active (e.g., twilight). Photopic vision is cone-only in bright light and scotopic vision is rod-only in darkness.'},
  {s:'Sensation & Perception',aamc:'6A',q:'_____ are a group of proteins in retinal photoreceptor cells that are made light-sensitive by the chromophore retinal',choices:['Transducins','Opsins','Crystallins','Phosphodiesterases'],ans:1,exp:'**Opsins** are G protein-coupled receptors that bind retinal; rhodopsin is the rod opsin and photopsins are the cone opsins. Transducin is the G protein that opsin activates next in the cascade.'},
  {s:'Sensation & Perception',aamc:'6A',q:'Photopsin is a biological pigment found in the _____ of the retina',choices:['rods','cones','bipolar cells','ganglion cells'],ans:1,exp:'**Cones** contain photopsins, with three variants tuned to short, medium, and long wavelengths, which is the basis of trichromatic color vision. Rods contain rhodopsin instead.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The ratio of rods to cones in the human retina is roughly _____',choices:['1:20','1:1','20:1','2:1'],ans:2,exp:'The retina has about 120 million rods and about 6 million cones, a ratio of roughly **20:1**. Cones are far fewer but are concentrated in the fovea, where acuity is highest.'},
  {s:'Sensation & Perception',aamc:'6A',q:'_____ are roughly 1,000 times more sensitive to light than _____',choices:['Rods / cones','Cones / rods','Ganglion cells / bipolar cells','Bipolar cells / rods'],ans:0,exp:'**Rods** are far more light-sensitive than **cones**, and many rods converge onto each ganglion cell, which suits them for dim-light (scotopic) vision. Cones need brighter light but provide color and high acuity.'},
  {s:'Sensation & Perception',aamc:'6A',q:'_____ predominate in the periphery of the retina, whereas _____ are concentrated in the fovea',choices:['Rods / cones','Cones / rods','Ganglion cells / bipolar cells','Rods / ganglion cells'],ans:0,exp:'**Rods** dominate the peripheral retina (dim light and motion detection), while **cones** are concentrated in the rod-free fovea, which gives the sharpest vision. This is why a faint star is easier to see when you look slightly to one side of it.'},
  {s:'Sensation & Perception',aamc:'6A',q:'There is a blind spot in each eye where the _____ leaves the retina',choices:['oculomotor nerve','ciliary body','optic nerve','suspensory ligament'],ans:2,exp:'The **optic nerve** exits at the optic disc, which has no photoreceptors and therefore creates a blind spot. The brain fills in the gap, and the two eyes\' blind spots do not overlap.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The _____ is an X-shaped structure formed where the optic nerves partially cross in the brain',choices:['optic tract','optic chiasm','lateral geniculate nucleus','optic radiation'],ans:1,exp:'At the **optic chiasm**, fibers from the nasal half of each retina cross to the opposite side. Fibers continue as the optic tracts to the lateral geniculate nucleus (LGN) of the thalamus and then via the optic radiations to the occipital cortex.'},
  {s:'Sensation & Perception',aamc:'6A',q:'All right visual field input is processed by the _____ hemisphere, and all left visual field input by the _____ hemisphere',choices:['right / left','left / left','left / right','right / right'],ans:2,exp:'Nasal retinal fibers cross at the optic chiasm, so each hemisphere receives the opposite visual field from both eyes: the right visual field goes to the **left** occipital cortex and the left visual field to the **right**. This is why a left occipital stroke causes a right homonymous hemianopia.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The _____ of color vision explains that there are three types of cones, each of which is most sensitive to a different range of light wavelengths',choices:['opponent-process theory','signal detection theory','feature detection theory','trichromatic theory'],ans:3,exp:'The **trichromatic (Young-Helmholtz) theory** proposes short-, medium-, and long-wavelength (blue, green, red) cones whose relative activation codes color; it explains color blindness at the receptor level. Opponent-process theory explains color coding at later stages (ganglion cells and the LGN).'},
  {s:'Sensation & Perception',aamc:'6A',q:'The _____ states that the visual system codes color in three opposing pairs: blue/yellow, red/green, and black/white',choices:['opponent-process theory','trichromatic theory','feature detection theory','signal detection theory'],ans:0,exp:'In **opponent-process theory** (Hering), activation of one member of a pair inhibits the other; this coding occurs in ganglion cells and the LGN. It explains negative afterimages, which trichromatic theory cannot.'},
  {s:'Sensation & Perception',aamc:'6A',q:'Humans cannot perceive certain color combinations, such as reddish-green or yellowish-blue. This is explained by the _____ of color vision',choices:['trichromatic theory','opponent-process theory','feature detection theory','signal detection theory'],ans:1,exp:'In **opponent-process theory**, red and green (and blue and yellow) are coded by the same cells as mutually inhibitory signals, so both cannot be signaled at once. The same mechanism produces complementary-colored afterimages after staring at a color.'},
  {s:'Sensation & Perception',aamc:'6A',q:'Audition is our sense of _____',choices:['balance','touch','hearing','smell'],ans:2,exp:'**Audition** is hearing: sound waves are transduced by cochlear hair cells. Balance is the vestibular sense, handled by the semicircular canals, utricle, and saccule.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The _____ is the receptor structure in the inner ear that transduces mechanical sound vibrations into nerve impulses',choices:['oval window','semicircular canal','tympanic membrane','organ of Corti'],ans:3,exp:'The **organ of Corti** in the cochlea contains the hair cells that convert vibrations into neural signals. The oval window only passes vibrations from the stapes into the cochlear fluid.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The organ of Corti rests on the _____ membrane, and the stereocilia of its hair cells contact the overlying _____ membrane',choices:['tectorial / basilar','basilar / tectorial','tympanic / basilar','Reissner\'s / tectorial'],ans:1,exp:'The organ of Corti sits on the **basilar** membrane; when it vibrates, hair cell stereocilia bend against the **tectorial** membrane, opening K⁺ channels and depolarizing the cell. Reissner\'s (vestibular) membrane separates the scala vestibuli from the scala media.'},
  {s:'Sensation & Perception',aamc:'6A',q:'_____ proposes that we hear different pitches because different sound frequencies maximally vibrate different places along the cochlea\'s basilar membrane',choices:['Frequency theory','Volley theory','Place theory','Gate control theory'],ans:2,exp:'**Place theory** says high frequencies peak near the base of the cochlea (narrow, stiff membrane) and low frequencies near the apex. Frequency theory instead says pitch is coded by the firing rate of auditory nerve fibers, which works mainly for low frequencies.'},
  {s:'Sensation & Perception',aamc:'6A',q:'Humans can hear sounds at frequencies between about _____ and _____ Hz',choices:['20 / 20,000','2 / 2,000','200 / 200,000','20 / 2,000'],ans:0,exp:'The normal human hearing range is about **20 Hz to 20,000 Hz** (20 kHz). The upper limit declines with age (presbycusis), starting with high frequencies.'},
  {s:'Sensation & Perception',aamc:'6A',q:'_____ is the process by which different sound frequencies stimulate different regions of the cochlea\'s basilar membrane',choices:['Phase locking','Basilar tuning','Sensory adaptation','Auditory masking'],ans:1,exp:'**Basilar tuning** reflects the membrane\'s graded width and stiffness: the stiff, narrow base resonates with high frequencies and the floppy, wide apex with low frequencies. Phase locking is instead neurons firing in time with the sound wave, which supports frequency theory.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The primary auditory cortex is part of the _____ and receives the cochlea\'s sound information (relayed through the medial geniculate nucleus)',choices:['temporal lobe','parietal lobe','frontal lobe','occipital lobe'],ans:0,exp:'The primary auditory cortex lies in the superior **temporal lobe** (Heschl\'s gyrus), near Wernicke\'s area. Mnemonic: the MGN (Medial = Music) relays sound, and the LGN (Lateral = Light) relays vision.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The primary auditory cortex is organized into regions that respond to different frequencies. This is called _____',choices:['retinotopic mapping','somatotopic mapping','tonotopic mapping','lateral inhibition'],ans:2,exp:'**Tonotopic mapping** preserves the cochlea\'s frequency order (base to apex) in the auditory cortex. Retinotopic and somatotopic maps are the visual and body-surface equivalents.'},
  {s:'Sensation & Perception',aamc:'6A',q:'A cochlear implant can provide a sense of sound to individuals with _____, also known as nerve deafness',choices:['conductive hearing loss','otosclerotic hearing loss','chronic tinnitus','sensorineural hearing loss'],ans:3,exp:'A cochlear implant bypasses damaged hair cells and stimulates the auditory nerve directly, so it treats **sensorineural hearing loss**. Conductive hearing loss (e.g., otosclerosis or a ruptured eardrum) affects the outer or middle ear and is treated with hearing aids or surgery.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The primary _____ receives sensory input from the body and is located in the _____',choices:['somatosensory cortex / parietal lobe','somatosensory cortex / frontal lobe','motor cortex / parietal lobe','motor cortex / frontal lobe'],ans:0,exp:'The primary **somatosensory cortex** is in the postcentral gyrus of the **parietal lobe** and is somatotopically organized (the sensory homunculus). The primary motor cortex is in the precentral gyrus of the frontal lobe and sends motor output rather than receiving body sensation.'},
  {s:'Sensation & Perception',aamc:'6A',q:'_____ is the sense that provides information about the movement of your body and limbs',choices:['Interoception','Nociception','Kinesthesia','Thermoception'],ans:2,exp:'**Kinesthesia** is the sense of body movement, detected by receptors in muscles, tendons, and joints; it is closely tied to proprioception (the sense of body position). Interoception senses internal organ states such as hunger or heartbeat.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The two main types of physical pain are _____ and _____',choices:['nociceptive pain / neuropathic pain','referred pain / phantom limb pain','psychogenic pain / referred pain','thermal pain / phantom limb pain'],ans:0,exp:'**Nociceptive pain** arises from nociceptors detecting actual or potential tissue damage, while **neuropathic pain** arises from damage or disease of the somatosensory nervous system itself. Referred and phantom limb pain are specific pain phenomena, not the two main categories.'},
  {s:'Sensation & Perception',aamc:'6A',q:'_____ is caused by potentially harmful stimuli being detected by receptors around the body',choices:['Neuropathic pain','Referred pain','Nociceptive pain','Phantom limb pain'],ans:2,exp:'**Nociceptive pain** begins at free nerve endings (nociceptors) that respond to tissue damage, carried by fast Aδ fibers (sharp pain) and slow C fibers (dull, aching pain). Neuropathic pain comes from damage to the nerves themselves.'},
  {s:'Sensation & Perception',aamc:'6A',q:'_____ is pain caused by damage or disease affecting the somatosensory nervous system',choices:['Nociceptive pain','Referred pain','Psychogenic pain','Neuropathic pain'],ans:3,exp:'**Neuropathic pain** (e.g., diabetic neuropathy, shingles) often burns or tingles and arises without ongoing tissue damage. Referred pain is pain from a visceral organ felt at a body-surface site (e.g., heart pain felt in the left arm).'},
  {s:'Sensation & Perception',aamc:'6A',q:'_____ is the sense by which an organism perceives temperature, or more accurately, infers temperature differences',choices:['Nociception','Mechanoreception','Thermoreception','Interoception'],ans:2,exp:'**Thermoreception** uses warm and cold receptors that respond to changes relative to skin temperature, which is why lukewarm water can feel hot or cold depending on prior exposure. Nociception detects damaging (including painfully hot) stimuli.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The _____ is a specialized epithelial tissue inside the nasal cavity that contains the receptor cells for smell',choices:['olfactory bulb','nasal turbinate','cribriform plate','olfactory epithelium'],ans:3,exp:'The **olfactory epithelium** in the roof of the nasal cavity contains olfactory receptor neurons, whose axons pass through the cribriform plate to the olfactory bulb. Each receptor neuron expresses one type of odorant receptor (a GPCR).'},
  {s:'Sensation & Perception',aamc:'6A',q:'The _____ is a sieve-like part of the ethmoid bone that supports the olfactory bulb',choices:['sella turcica','cribriform plate','crista galli','foramen magnum'],ans:1,exp:'Olfactory nerve fibers pass through the many holes of the **cribriform plate**, so a fracture there can cause anosmia and CSF leaking from the nose. The sella turcica is the sphenoid depression that holds the pituitary gland.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The _____ is a forebrain structure resting on the cribriform plate that receives the axons of olfactory receptor neurons projecting up from the olfactory epithelium',choices:['olfactory epithelium','olfactory bulb','piriform cortex','thalamus'],ans:1,exp:'Olfactory receptor neurons send axons (CN I) through the cribriform plate to synapse in the **olfactory bulb**; mitral and tufted cells then project via the olfactory tract to the olfactory (piriform) cortex. Unlike the other senses, this pathway does not relay through the thalamus first.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The olfactory bulb contains thousands of _____, where olfactory nerve terminals synapse with the dendrites of mitral, periglomerular, and tufted cells',choices:['nuclei','glomeruli','ganglia','papillae'],ans:1,exp:'Each olfactory **glomerulus** receives input from receptor neurons that express the same odorant receptor, creating an odor map in the bulb. Papillae are tongue structures that house taste buds.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The sense of _____ is the only human sense whose primary pathway bypasses the thalamus and connects directly to the forebrain',choices:['taste','smell','touch','hearing'],ans:1,exp:'**Smell** (olfaction) projects from the olfactory bulb straight to the olfactory cortex and limbic structures (amygdala, hippocampus), which helps explain why odors evoke strong emotional memories. Taste, touch, hearing, and vision all relay through the thalamus.'},
  {s:'Sensation & Perception',aamc:'6A',q:'_____ is the partial or complete loss of the sense of smell',choices:['Ageusia','Agnosia','Anosmia','Aphasia'],ans:2,exp:'**Anosmia** is loss of smell (seen after head trauma, viral infection such as COVID-19, or in early Parkinson\'s disease). Ageusia is loss of taste, and agnosia is the inability to recognize objects despite intact sensation.'},
  {s:'Sensation & Perception',aamc:'6A',q:'_____ is the sense of taste',choices:['Olfaction','Gustation','Audition','Kinesthesia'],ans:1,exp:'**Gustation** detects five basic tastes (sweet, sour, salty, bitter, umami). Olfaction (smell) contributes much of what we experience as "flavor."'},
  {s:'Sensation & Perception',aamc:'6A',q:'_____ are small protrusions on the surface of the tongue that contain taste buds',choices:['Papillae','Microvilli','Rugae','Glomeruli'],ans:0,exp:'**Papillae** (fungiform, foliate, circumvallate; filiform papillae have no taste buds) house the taste buds. Microvilli are the tiny projections on individual taste receptor cells that reach the taste pore.'},
  {s:'Sensation & Perception',aamc:'6A',q:'_____ are barrel-shaped structures that consist of many gustatory receptor cells',choices:['Papillae','Taste buds','Taste pores','Glomeruli'],ans:1,exp:'Each **taste bud** contains about 50 to 100 receptor cells whose microvilli project into a taste pore. Taste buds sit within papillae; the papillae are the visible bumps on the tongue.'},
  {s:'Sensation & Perception',aamc:'6A',q:'The fungiform papillae, which contain taste buds, are concentrated at the _____ of the tongue',choices:['back','midline','front','underside'],ans:2,exp:'Fungiform papillae are most dense at the **front** (tip and sides) of the tongue. The large circumvallate papillae form a V across the back of the tongue, and taste buds are also present elsewhere in the mouth and throat.'},
  {s:'Sensation & Perception',aamc:'6A',q:'A single taste bud contains receptor cells capable of detecting _____ of the basic tastes',choices:['only 1','only 2','only 3','all 5'],ans:3,exp:'Each taste bud has receptor cells for **all 5** basic tastes (sweet, sour, salty, bitter, umami). The "tongue map" with separate regions for single tastes is a myth.'},
  {s:'Biological Bases of Behavior',aamc:'6B',q:'A _____ is a vivid, dream-like sensation that an individual hears, sees, feels, or even smells as they are falling asleep',choices:['hypnopompic hallucination','hypnagogic hallucination','night terror','hypnic jerk'],ans:1,exp:'**Hypnagogic** hallucinations occur while falling asleep (mnemonic: the "g" in hypna**g**ogic means "**g**oing" to sleep). Hypnopompic hallucinations occur while waking up; both are common in narcolepsy.'},
  {s:'Biological Bases of Behavior',aamc:'6B',q:'The _____ occurs when people devote so much time and attention to an activity that it begins to shape their thoughts, mental images, and dreams',choices:['Zeigarnik effect','mere exposure effect','Tetris effect','priming effect'],ans:2,exp:'The **Tetris effect** is named for players who saw falling blocks in their hypnagogic imagery and dreams after long play sessions. The Zeigarnik effect is the tendency to remember unfinished tasks better than finished ones.'},
  {s:'Biological Bases of Behavior',aamc:'6B',q:'A _____ is an involuntary twitch that occurs as a person is beginning to fall asleep, often causing them to jolt awake for a moment',choices:['cataplexy episode','sleep paralysis episode','night terror','hypnic jerk'],ans:3,exp:'A **hypnic jerk** is a benign myoclonic twitch at sleep onset (stage N1). Cataplexy, by contrast, is a sudden loss of muscle tone triggered by strong emotion and is characteristic of narcolepsy.'},
  {s:'Biological Bases of Behavior',aamc:'6B',q:'Dreams often contain illogical images and events. This is partly because activity in the _____ is decreased during REM sleep',choices:['visual association cortex','amygdala','prefrontal cortex','pons'],ans:2,exp:'During REM sleep the **prefrontal cortex** (logic, planning, self-monitoring) is relatively inactive, so bizarre dream events go unquestioned. The amygdala, visual association areas, and pons are more active in REM, which fits dreams\' vivid, emotional quality.'},
  {s:'Biological Bases of Behavior',aamc:'6B',q:'Sigmund Freud believed that dreams are a disguised expression of _____',choices:['random byproducts of brainstem activation','rehearsals for responding to threats','our unconscious thoughts and desires','a way of consolidating the day\'s memories'],ans:2,exp:'In Freud\'s wish-fulfillment theory, dreams express **unconscious wishes and desires** in disguised form, with latent content hidden behind manifest content. Random brainstem activation is instead the basis of the activation-synthesis theory.'},
  {s:'Biological Bases of Behavior',aamc:'6B',q:'The _____ of dreaming states that dreaming functions to simulate threatening events so that we can rehearse perceiving and avoiding threats',choices:['activation-synthesis theory','wish-fulfillment theory','memory consolidation theory','evolutionary theory'],ans:3,exp:'The **evolutionary (threat-simulation) theory** argues that dreams were selected for because rehearsing danger improved survival. Activation-synthesis theory instead treats dreams as the cortex making sense of random pontine (brainstem) signals.'},
  {s:'Biological Bases of Behavior',aamc:'6B',q:'The _____ of dreaming states that we use our dreams to sort out the problems and stresses of our day',choices:['problem-solving dream model','activation-synthesis theory','memory consolidation theory','wish-fulfillment theory'],ans:0,exp:'The **problem-solving dream model** holds that dreams, free of real-world constraints, let us work through current problems and stresses. Memory consolidation theories instead say sleep and dreaming help store and integrate new memories.'},
  {s:'Biological Bases of Behavior',aamc:'6B',q:'In Freud\'s wish-fulfillment theory of dreams, the _____ content is the literal storyline of the dream, whereas the _____ content is the hidden meaning behind its symbols',choices:['latent / manifest','manifest / latent','manifest / preconscious','conscious / latent'],ans:1,exp:'**Manifest** content is what the dream appears to be about, and **latent** content is the unconscious wish it disguises. Mnemonic: manifest = "made obvious"; latent = "lying hidden."'},
  {s:'Biological Bases of Behavior',aamc:'6B',q:'Sleepwalking occurs during _____, which corresponds to sleep stage _____',choices:['slow-wave sleep / N3','REM sleep / N1','slow-wave sleep / N1','light sleep / N2'],ans:0,exp:'Sleepwalking (somnambulism) and night terrors are parasomnias of **slow-wave sleep (N3)**, the deepest NREM stage with delta waves. They cannot occur in REM because REM involves muscle atonia; acting out dreams in REM is a separate disorder (REM sleep behavior disorder).'},
  {s:'Emotion, Motivation & Stress',aamc:'6B',q:'_____ holds that hypnotized people change their behavior to meet the demands of the social situation, acting out the role of a hypnotized subject rather than entering an altered state of consciousness',choices:['Dissociation theory','Activation-synthesis theory','Drive-reduction theory','Social influence theory'],ans:3,exp:'**Social influence theory** explains hypnosis as role-playing driven by expectations and social pressure. Dissociation theory (Hilgard) instead proposes a true split in consciousness, with a "hidden observer" that remains aware.'},
  {s:'Biological Bases of Behavior',aamc:'6B',q:'The most widely used depressant is _____',choices:['alcohol','barbiturates','benzodiazepines','opioids'],ans:0,exp:'**Alcohol** enhances GABA-A activity and inhibits NMDA glutamate receptors, causing sedation, disinhibition, and impaired judgment. Benzodiazepines and barbiturates are also GABA-A depressants, but they are prescription drugs used far less widely.'},
  {s:'Biological Bases of Behavior',aamc:'6B',q:'_____ are older sedative-hypnotics, once widely used for anxiety, insomnia, and seizures, that have a narrow therapeutic window and a high risk of fatal overdose',choices:['Opioids','Barbiturates','Antipsychotics','SSRIs'],ans:1,exp:'**Barbiturates** (e.g., phenobarbital) increase the duration of GABA-A chloride channel opening and can activate it directly, so overdose is often fatal. Benzodiazepines largely replaced them because they only increase the frequency of channel opening and are safer.'},
  {s:'Biological Bases of Behavior',aamc:'6B',q:'_____ are a class of tranquilizers that enhance GABA-A receptor activity; familiar examples include Valium (diazepam) and Xanax (alprazolam)',choices:['Barbiturates','SSRIs','Opioids','Benzodiazepines'],ans:3,exp:'**Benzodiazepines** increase the frequency of GABA-A chloride channel opening, producing anxiolytic, sedative, and anticonvulsant effects. Barbiturates also act on GABA-A but are older and more dangerous; the "-azepam/-azolam" names mark the benzodiazepines.'},
  {s:'Biological Bases of Behavior',aamc:'6B',q:'The primary mind-altering ingredient in marijuana is _____',choices:['CBD','THC','anandamide','psilocybin'],ans:1,exp:'**THC** (Δ⁹-tetrahydrocannabinol) activates CB1 cannabinoid receptors to produce the high. CBD (cannabidiol) is also found in cannabis but is not intoxicating, and anandamide is the body\'s own (endogenous) cannabinoid.'},
  {s:'Biological Bases of Behavior',aamc:'6B',q:'_____, commonly known as ecstasy, is a synthetic drug that acts as both a stimulant and a hallucinogen',choices:['LSD','PCP','MDMA','Methamphetamine'],ans:2,exp:'**MDMA** releases large amounts of serotonin (plus dopamine and norepinephrine), producing euphoria, empathy, and hyperthermia. Methamphetamine is a pure stimulant, and LSD is a pure hallucinogen.'},
  {s:'Biological Bases of Behavior',aamc:'6B',q:'_____ is a natural stimulant most commonly found in tea, coffee, and cacao plants',choices:['Nicotine','Caffeine','Cocaine','Ephedrine'],ans:1,exp:'**Caffeine** is an adenosine receptor antagonist; blocking adenosine\'s sleep-promoting signal increases alertness. Nicotine is a stimulant from tobacco that acts on nicotinic acetylcholine receptors.'},
  {s:'Biological Bases of Behavior',aamc:'6B',q:'_____ is the addictive drug in tobacco products',choices:['Tar','Carbon monoxide','Formaldehyde','Nicotine'],ans:3,exp:'**Nicotine** stimulates nicotinic acetylcholine receptors and increases dopamine release in the mesolimbic reward pathway (nucleus accumbens). Tar and carbon monoxide cause much of smoking\'s harm but are not what makes it addictive.'},
  {s:'Biological Bases of Behavior',aamc:'6B',q:'_____ occurs when the body adapts to a drug so that more of it is needed to achieve the same effect',choices:['Withdrawal','Tolerance','Sensitization','Cross-tolerance'],ans:1,exp:'**Tolerance** results from adaptations such as receptor downregulation and faster metabolism. Sensitization is the opposite: a drug\'s effect grows stronger with repeated use.'},
  {s:'Biological Bases of Behavior',aamc:'6B',q:'_____ is a phenomenon in which tolerance to one drug produces tolerance to a second drug',choices:['Sensitization','Synergism','Cross-tolerance','Potentiation'],ans:2,exp:'**Cross-tolerance** occurs between drugs with similar mechanisms (e.g., alcohol, benzodiazepines, and barbiturates all act on GABA-A). This is why benzodiazepines can be used to manage alcohol withdrawal.'},
  {s:'Biological Bases of Behavior',aamc:'6B',q:'_____ are physical and mental symptoms that occur after a person stops or reduces regular use of a drug',choices:['Intoxication symptoms','Overdose symptoms','Tolerance effects','Withdrawal symptoms'],ans:3,exp:'**Withdrawal symptoms** are generally the opposite of the drug\'s effects (e.g., stimulant withdrawal causes fatigue and depression). Alcohol and benzodiazepine withdrawal can be life-threatening because of seizures, whereas opioid withdrawal is miserable but rarely fatal.'},
  {s:'Biological Bases of Behavior',aamc:'7A',q:'_____ is a form of psychotherapy that focuses on how a person\'s thoughts, beliefs, and attitudes affect their feelings and behaviors',choices:['Psychodynamic therapy','Cognitive behavioral therapy','Humanistic therapy','Interpersonal therapy'],ans:1,exp:'**Cognitive behavioral therapy (CBT)** identifies and restructures maladaptive thoughts and uses behavioral techniques such as exposure; it is a first-line treatment for depression and anxiety. Psychodynamic therapy instead explores unconscious conflicts and early experiences.'},
  {s:'Biological Bases of Behavior',aamc:'7C',q:'_____ is a counseling method that helps people resolve ambivalent feelings and insecurities to find the internal motivation they need to change their behavior',choices:['Motivational interviewing','Psychoanalysis','Aversion therapy','Cognitive behavioral therapy'],ans:0,exp:'**Motivational interviewing** is client-centered and elicits the person\'s own reasons for change, which makes it useful for substance use. Aversion therapy instead pairs an unwanted behavior with an unpleasant stimulus.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is the deliberate allocation of attention to specific information or cognitive processes',choices:['Divided attention','Sustained attention','Directed attention','Attentional capture'],ans:2,exp:'**Directed attention** is voluntary, effortful focus on a chosen target, and it fatigues with prolonged use. Attentional capture is the opposite: attention pulled involuntarily by a salient stimulus.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'An attention cue that comes from outside the person and captures attention automatically is called _____',choices:['endogenous','exogenous','covert','overt'],ans:1,exp:'**Exogenous** ("from outside") cues, such as a sudden flash or loud noise, draw attention reflexively (bottom-up). Endogenous cues are internal and voluntary (top-down), such as following an arrow to a location.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'An attention cue that comes from within the person and produces a willful shift of attention is called _____',choices:['endogenous','exogenous','covert','overt'],ans:0,exp:'**Endogenous** ("from within") attention is goal-driven and voluntary (top-down). Exogenous attention is involuntarily captured by external stimuli (bottom-up).'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'The _____ refers to the ability to focus one\'s attention on a particular stimulus while filtering out a range of other stimuli (i.e., noise)',choices:['Stroop effect','attentional blink','change blindness','cocktail party effect'],ans:3,exp:'The **cocktail party effect** shows selective attention to one conversation, yet salient unattended information (such as your own name) can still break through. The Stroop effect is slowed color naming when a word names a different color.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____, also known as _____, is the failure to notice something in plain sight because attention is focused closely on something else',choices:['Inattentional blindness / perceptual blindness','Change blindness / attentional blink','Hemispatial neglect / hemineglect','Selective attention / cocktail party effect'],ans:0,exp:'**Inattentional (perceptual) blindness** is missing a fully visible but unexpected object while attention is engaged elsewhere (e.g., the "invisible gorilla" study). Change blindness is a related but different failure: not noticing that something in a scene has changed.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is a perceptual phenomenon in which an observer fails to notice that something in a visual scene has changed',choices:['Inattentional blindness','Change blindness','Attentional blink','Blindsight'],ans:1,exp:'**Change blindness** shows that we store little detail from one view to the next (e.g., not noticing that a conversation partner was swapped). Blindsight is responding accurately to visual stimuli without conscious sight, after damage to the primary visual cortex.'},
  {s:'Cognition, Learning & Memory',aamc:'6A',q:'_____ are the actual objects and events out in the world around you',choices:['Proximal stimuli','Subliminal stimuli','Distal stimuli','Conditioned stimuli'],ans:2,exp:'**Distal stimuli** are the real-world objects themselves (e.g., a tree). Proximal stimuli are the patterns of energy from them that reach the sense organs (e.g., the tree\'s image on the retina).'},
  {s:'Cognition, Learning & Memory',aamc:'6A',q:'_____ are the patterns of energy from objects and events that actually reach your sense organs (eyes, ears, etc.)',choices:['Distal stimuli','Proximal stimuli','Subliminal stimuli','Conditioned stimuli'],ans:1,exp:'**Proximal stimuli** are what the receptors actually receive, such as a retinal image that shrinks as an object moves away. Perception reconstructs the distal stimulus (the unchanged object) from them.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is the act of mentally shifting one\'s focus without moving one\'s eyes',choices:['Overt orienting','Covert orienting','Attentional capture','Divided attention'],ans:1,exp:'**Covert orienting** moves the "spotlight" of attention without eye movement (e.g., watching someone out of the corner of your eye). Overt orienting moves the eyes or head toward the target.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is the act of selectively attending to an item or location by moving the eyes to point in that direction',choices:['Covert orienting','Attentional capture','Overt orienting','Divided attention'],ans:2,exp:'**Overt orienting** involves visible eye or head movements, such as saccades toward a target. Covert orienting shifts attention internally while the gaze stays fixed.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ occurs when attention is involuntarily drawn by a salient stimulus, such as a moving or suddenly appearing object',choices:['Covert orienting','Inhibition of return','Sustained attention','Attentional capture'],ans:3,exp:'**Attentional capture** is bottom-up (exogenous): motion and abrupt onsets grab attention automatically. Inhibition of return is the opposite tendency to be slower to re-attend to a location that was just attended.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is a neuropsychological condition in which damage to the right parietal lobe causes a person to ignore the left side of their world, and even the left side of their own body',choices:['Prosopagnosia','Hemispatial neglect','Blindsight','Homonymous hemianopia'],ans:1,exp:'**Hemispatial neglect** (neglect syndrome) is an attentional deficit, not a visual one: patients may eat only from the right side of the plate or shave only half of their face. Homonymous hemianopia, by contrast, is true loss of half the visual field, and patients compensate by turning their heads.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____, also termed sustained concentration, is the ability to maintain concentrated attention over prolonged periods of time',choices:['Vigilance','Divided attention','Selective attention','Attentional capture'],ans:0,exp:'**Vigilance** (sustained attention) is needed for tasks such as air-traffic control, and performance declines over time (the vigilance decrement). Divided attention is splitting attention among several tasks at once.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is involved in goal-directed behavior, monitoring conflicts between internal processes, and anticipating the effects of behavior',choices:['Selective attention','Divided attention','Vigilance','Executive attention'],ans:3,exp:'**Executive attention** is the top-down control network (prefrontal cortex and anterior cingulate) that resolves conflict, as in the Stroop task. Vigilance is simply sustaining attention over time.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'In a _____, a participant wears headphones, hears a different message in each ear, and is asked to repeat aloud only one of the messages',choices:['Stroop task','shadowing task','visual search task','change detection task'],ans:1,exp:'In a **shadowing task** (Cherry\'s dichotic listening studies), people noticed little of the unattended message beyond physical features such as a voice changing from male to female. This finding inspired Broadbent\'s early selection filter model.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ states that all sensory information enters a sensory buffer, and a filter then selects one input for further processing based on its physical characteristics, before its meaning is analyzed',choices:['Treisman\'s attenuation theory','Deutsch and Deutsch\'s late selection theory','Broadbent\'s early selection theory','Kahneman\'s resource model'],ans:2,exp:'**Broadbent\'s early selection theory**: sensory buffer → selective filter (based on physical features) → perceptual processing → conscious awareness, so unattended input is never processed for meaning. It cannot explain the cocktail party effect, which motivated the later models.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'The _____ states that all information, both attended and unattended, undergoes analysis for meaning, and only after that analysis does selection of an input for conscious awareness take place',choices:['Deutsch and Deutsch late selection theory','Broadbent early selection theory','Treisman attenuation theory','Kahneman resource model'],ans:0,exp:'In the **Deutsch and Deutsch late selection theory**, the filter comes after semantic processing, which explains why your name can grab your attention from an unattended conversation. Broadbent placed the filter before meaning is analyzed.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ proposes that unattended information is weakened ("turned down") rather than completely blocked, so personally important unattended stimuli can still reach awareness',choices:['Broadbent\'s early selection theory','Treisman\'s attenuation theory','Deutsch and Deutsch\'s late selection theory','Kahneman\'s resource model'],ans:1,exp:'**Treisman\'s attenuation theory** is a compromise: unattended input is attenuated like a volume knob, and words with low thresholds (e.g., your name) can still get through. Broadbent\'s model, by contrast, blocks unattended input completely.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'The _____ describes attention as a movable zone directed at one location in space: everything inside the zone is processed preferentially, while information outside it is unattended',choices:['resource model of attention','spotlight model of attention','filter model of attention','feature integration theory'],ans:1,exp:'The **spotlight model** treats spatial attention like a beam of light that can shift (even covertly) to enhance processing at one location. The resource model instead focuses on attention as a limited capacity that is divided among tasks.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is the implicit memory effect in which exposure to one stimulus influences the response to a later stimulus',choices:['Habituation','Priming','Proactive interference','Encoding specificity'],ans:1,exp:'**Priming** works through spreading activation: seeing "doctor" speeds recognition of "nurse" without conscious awareness. Proactive interference is old learning disrupting the recall of new learning.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'The _____ states that we have limited resources for attention, and those resources are easily overtaxed if we try to pay attention to multiple things at once',choices:['spotlight model of attention','early selection model of attention','late selection model of attention','resource model of attention'],ans:3,exp:'The **resource model** (e.g., Kahneman\'s capacity model) explains why multitasking fails, especially when tasks draw on the same resource type (e.g., two verbal tasks). Selection models instead ask where in processing a filter acts.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ memory refers to auditory sensory memory, whereas _____ memory refers to visual sensory memory',choices:['Iconic / echoic','Echoic / iconic','Haptic / echoic','Echoic / haptic'],ans:1,exp:'**Echoic** memory (echo = sound) is auditory sensory memory lasting about 3 to 4 seconds; **iconic** memory (icon = image) is visual sensory memory lasting under 1 second. Haptic memory is sensory memory for touch.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'In iconic memory experiments, the _____ requires participants to recall as many elements from the entire original visual display as possible',choices:['partial report technique','whole report technique','free recall technique','serial recall technique'],ans:1,exp:'In Sperling\'s **whole report technique**, people recall only about 4 of 12 letters because the icon fades while they report. With the partial report technique (a tone cues a single row), nearly any row can be recalled, which shows that the icon briefly holds almost the entire display.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'The serial-position effect is the tendency of a person to recall the first and last items in a series _____ and the middle items _____',choices:['worst / best','best / best','best / worst','worst / worst'],ans:2,exp:'In the serial-position effect, the primacy effect (early items rehearsed into long-term memory) and the recency effect (late items still in short-term memory) make the first and last items recalled **best** and the middle items **worst**. A delay before recall removes the recency effect but not the primacy effect.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'The _____ is the component of working memory responsible for handling visual and spatial information',choices:['phonological loop','central executive','episodic buffer','visuospatial sketchpad'],ans:3,exp:'In Baddeley\'s model, the **visuospatial sketchpad** holds images and spatial layouts (e.g., mentally rotating an object). The phonological loop handles verbal and auditory information.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'The phonological loop is a component of Baddeley\'s working memory model that deals with _____ information',choices:['visual','spatial','auditory','tactile'],ans:2,exp:'The phonological loop holds verbal and **auditory** information through subvocal rehearsal (e.g., repeating a phone number). Visual and spatial information is handled by the visuospatial sketchpad.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'The _____ acts as a supervisory system and controls the flow of information to and from its slave systems, the phonological loop and the visuospatial sketchpad',choices:['episodic buffer','central executive','phonological store','sensory register'],ans:1,exp:'The **central executive** directs attention and coordinates the subsystems; it is associated with the prefrontal cortex. The episodic buffer, added to the model later, is a further slave system that integrates information and links it to long-term memory.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'The _____ states that visual and verbal information are coded separately in the brain',choices:['levels of processing model','spreading activation model','multi-store model','dual coding hypothesis'],ans:3,exp:'Paivio\'s **dual coding hypothesis** explains why concrete words (which can be stored both as an image and as a word) are remembered better than abstract ones. The levels of processing model instead says that deeper (semantic) processing produces more durable memories.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is a memory system consisting of episodes recollected from an individual\'s life, based on a combination of episodic and semantic memory',choices:['Procedural memory','Semantic memory','Implicit memory','Autobiographical memory'],ans:3,exp:'**Autobiographical memory** combines specific events (episodic) with facts about oneself (semantic) to form a life story. Procedural memory is implicit memory for skills, such as riding a bike.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'The _____ principle states that memories are more easily retrieved when the cues present at retrieval match those present when the memory was encoded',choices:['levels of processing','encoding specificity','spacing','retroactive interference'],ans:1,exp:'**Encoding specificity** (Tulving) underlies context-dependent memory (same place) and state-dependent memory (same internal state). The levels of processing principle concerns how deeply information is processed, not whether retrieval cues match.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is deliberate, continuous repetition of material in the same form in which it entered working memory',choices:['Elaborative rehearsal','Chunking','Rote rehearsal','Spaced repetition'],ans:2,exp:'**Rote (maintenance) rehearsal** keeps information in short-term memory but transfers it to long-term memory poorly. Elaborative rehearsal links new information to existing knowledge and produces much better retention.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is a process by which individual pieces of information are grouped together into larger meaningful units',choices:['Rote rehearsal','Chunking','Elaborative rehearsal','Method of loci'],ans:1,exp:'**Chunking** expands short-term memory\'s limited capacity (Miller\'s 7 ± 2 items) by grouping, as in remembering a phone number as 3-3-4 digits. The method of loci instead links items to familiar locations.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'Any learning technique that aids the retention or retrieval of information in memory is called a _____',choices:['schema','heuristic','prototype','mnemonic device'],ans:3,exp:'A **mnemonic device** (acronyms, rhymes, method of loci, peg-word system) adds structure or imagery to aid encoding and retrieval. A heuristic is a mental shortcut for problem solving, not a memory aid.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'The _____ is the tendency to remember information better when it is encoded in relation to oneself',choices:['spacing effect','self-reference effect','serial-position effect','generation effect'],ans:1,exp:'The **self-reference effect** reflects deep, elaborative encoding: relating material to yourself ties it to a rich, well-organized self-schema. The generation effect is better memory for information you produce yourself than for information you only read.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'The _____ is the phenomenon whereby learning is greater when study sessions are spread out over time rather than massed together',choices:['testing effect','serial-position effect','self-reference effect','spacing effect'],ans:3,exp:'The **spacing effect** (distributed practice) beats cramming (massed practice) for long-term retention. The testing effect is the separate finding that practicing retrieval strengthens memory more than rereading does.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is the improved recall of specific episodes or information when the external environment at encoding and at retrieval is the same',choices:['State-dependent memory','Mood-congruent memory','Context-dependent memory','Retroactive interference'],ans:2,exp:'**Context-dependent memory**: divers who learned words underwater recalled them better underwater. State-dependent memory is the same idea for internal states, such as being intoxicated or in a particular mood, rather than the external setting.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is the phenomenon in which memory retrieval is most efficient when an individual is in the same internal state of consciousness as when the memory was formed',choices:['State-dependent memory','Context-dependent memory','Mood-congruent memory','Proactive interference'],ans:0,exp:'**State-dependent memory** applies to internal physiological or emotional states (e.g., information learned while caffeinated is best recalled while caffeinated). Mood-congruent memory is different: we preferentially recall memories whose emotional tone matches our current mood.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is the retrieval of a memory with the help of cues',choices:['Free recall','Recognition','Relearning','Cued recall'],ans:3,exp:'**Cued recall** provides hints (e.g., the first letter of a word) and falls between free recall (no cues, hardest) and recognition (choosing from options, easiest). Relearning measures memory by the savings in time needed to learn material again.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'People use _____ to organize current knowledge and provide a framework for future understanding',choices:['heuristics','algorithms','prototypes','schemata'],ans:3,exp:'**Schemata** (schemas) are mental frameworks, such as a "restaurant script," that guide interpretation and can distort memory toward what is expected. A prototype is the single most typical member of a category.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'A _____ is a memory error in which a remembered detail is attributed to the wrong source, such as recalling something you were told as something you saw',choices:['source-monitoring error','misinformation effect','confabulation','retroactive interference'],ans:0,exp:'A **source-monitoring error** is remembering the content correctly but misattributing where it came from (e.g., believing a dream really happened). Confabulation is filling memory gaps with fabricated details, as in Korsakoff syndrome.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'A _____ is a highly detailed, exceptionally vivid "snapshot" of the moment and circumstances in which an emotionally significant event was learned about',choices:['flashbulb memory','eidetic image','procedural memory','false memory'],ans:0,exp:'A **flashbulb memory** feels vivid and is held with high confidence, but its accuracy decays like that of other memories; the amygdala boosts its emotional intensity. An eidetic (photographic) image is a rare, detailed visual memory that is not tied to emotion.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is a long-lasting strengthening of the synapses between neurons following repeated stimulation',choices:['Long-term depression','Long-term potentiation','Habituation','Synaptic pruning'],ans:1,exp:'**Long-term potentiation (LTP)**, best studied in the hippocampus, depends on NMDA receptor activation and Ca²⁺ influx; it is a cellular basis of learning and memory. Long-term depression is the opposite: a lasting weakening of synaptic strength.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is the ability of synapses, the junctions through which neurons communicate, to change their strength over time',choices:['Neurogenesis','Myelination','Synaptic plasticity','Saltatory conduction'],ans:2,exp:'**Synaptic plasticity** includes LTP and long-term depression and underlies learning. Neurogenesis is the birth of new neurons, which in adults is limited mainly to the hippocampus.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'The _____ proposes that memories fade simply because of the passage of time',choices:['interference theory','retrieval failure theory','motivated forgetting theory','decay theory'],ans:3,exp:'**Decay theory** says memory traces weaken with disuse over time. Interference theory instead blames competing memories: proactive (old disrupts new) or retroactive (new disrupts old).'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'If you forget something and then relearn it, the second learning is faster than the first. This is called the _____',choices:['savings effect','spacing effect','testing effect','recency effect'],ans:0,exp:'Ebbinghaus\'s **savings effect** shows that some memory trace remains even when recall fails. He also described the forgetting curve: rapid loss soon after learning, followed by a slower decline.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is remembering to perform an intended action in the future, such as taking a medication at 8 p.m.',choices:['Retrospective memory','Episodic memory','Prospective memory','Procedural memory'],ans:2,exp:'**Prospective memory** is "remembering to remember" and depends heavily on the prefrontal cortex. Retrospective memory is remembering past events or information.'},
  {s:'Personality, Development & Disorders',aamc:'6B',q:'Wernicke encephalopathy is an acute neurological disorder caused by thiamine (vitamin B1) deficiency, often in chronic alcohol use, that can progress to _____',choices:['Alzheimer disease','Korsakoff syndrome','Parkinson disease','Huntington disease'],ans:1,exp:'Wernicke encephalopathy (confusion, ataxia, and abnormal eye movements) can progress to **Korsakoff syndrome**, which features severe anterograde and some retrograde amnesia with confabulation. Alzheimer disease is a progressive neurodegenerative dementia unrelated to thiamine.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'The _____ refers to organizing categories and representations so that they are as simple as possible while still being useful',choices:['encoding specificity principle','cognitive economy principle','levels of processing principle','availability principle'],ans:1,exp:'The **cognitive economy principle** is why, in the hierarchical network model, a property such as "breathes" is stored once at "animal" rather than at every animal. Encoding specificity is about matching retrieval cues to encoding conditions.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'The _____ states that each individual\'s semantic network develops from personal experience and knowledge, with concepts linked by relatedness rather than by a required hierarchical order',choices:['hierarchical network model','feature comparison model','prototype model','modified semantic network model'],ans:3,exp:'The **modified semantic network model** (Collins and Loftus) links concepts by associative strength, and activation spreads along these links. It replaced the strict hierarchical network model (Collins and Quillian), which stored concepts in fixed category levels.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'The _____ states that concepts are linked in a network, so retrieving one concept also partially activates related concepts',choices:['hierarchical network model','dual coding hypothesis','spreading activation model','levels of processing model'],ans:2,exp:'The **spreading activation model** explains semantic priming: thinking of "fire truck" partially activates "red" and "siren." Dual coding concerns separate verbal and visual codes, not links between concepts.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ have specific goals, clearly defined solution paths, and clear expected solutions',choices:['Ill-defined problems','Insight problems','Well-defined problems','Divergent problems'],ans:2,exp:'**Well-defined problems** (e.g., solving an equation) can often be solved with algorithms. Ill-defined problems (e.g., "write a good essay") lack clear goals or solution paths and usually need heuristics and creativity.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ are those that do not have clear goals, solution paths, or expected solutions',choices:['Well-defined problems','Ill-defined problems','Algorithmic problems','Routine problems'],ans:1,exp:'**Ill-defined problems** (e.g., choosing a career) require defining the problem itself before solving it. Well-defined problems have a clear start, goal, and procedure for getting there.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is a basic method of problem solving characterized by repeated, varied attempts that continue until success or until the person stops trying',choices:['Means-ends analysis','Working backward','Insight','Trial and error'],ans:3,exp:'**Trial and error** works when there are few possible solutions but is inefficient for complex problems. Means-ends analysis is more strategic, repeatedly reducing the difference between the current state and the goal.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'A clearly defined, step-by-step procedure that is guaranteed to solve a problem is called _____',choices:['a heuristic','an insight','an algorithm','a mental set'],ans:2,exp:'**An algorithm** guarantees a correct solution but can be slow. A heuristic is a mental shortcut that is fast but can lead to errors.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'In _____, one solves a problem by identifying the differences (obstacles) between the current problem state and the goal state and setting subgoals to reduce them',choices:['working backward','trial and error','incubation','means-ends analysis'],ans:3,exp:'**Means-ends analysis** breaks a problem into subgoals, each of which narrows the gap to the goal. Working backward starts from the goal and traces steps back to the starting state.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is arriving at ideas or judgments without knowing exactly how or where they came from',choices:['Insight','Intuition','Incubation','Fixation'],ans:1,exp:'**Intuition** is a fast, non-conscious judgment, often based on accumulated experience (System 1 thinking). Insight is the sudden "aha" moment when the solution to a problem becomes clear.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'In problem solving, the term _____ refers to the inability to see a problem from a fresh perspective',choices:['incubation','insight','overconfidence','fixation'],ans:3,exp:'**Fixation** includes mental set (sticking with a method that worked before) and functional fixedness (seeing objects only in their usual use). Incubation, stepping away from a problem, can help break fixation.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'In problem solving, _____ is setting a problem aside for a while, after which a solution may come more easily',choices:['fixation','insight','incubation','mental set'],ans:2,exp:'**Incubation** may work by letting fixation fade and allowing unconscious processing to continue. Mental set is the opposite problem: persistently applying an approach that worked before.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'The _____ occurs when people assume that multiple specific conditions occurring together are more probable than a single general one',choices:['gambler\'s fallacy','conjunction fallacy','base-rate fallacy','sunk cost fallacy'],ans:1,exp:'The **conjunction fallacy** (Tversky and Kahneman\'s "Linda problem") violates the rule that the probability of two events together can never exceed the probability of either one alone, and it is driven by the representativeness heuristic. The gambler\'s fallacy is believing that past random events change future odds.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'The _____ occurs when people start from an initial reference point (the anchor) and then make insufficient adjustments to it to reach their estimate',choices:['availability heuristic','representativeness heuristic','anchoring and adjustment heuristic','simulation heuristic'],ans:2,exp:'The **anchoring and adjustment heuristic** explains why a high opening price in a negotiation pulls final offers upward. The availability heuristic instead judges likelihood by how easily examples come to mind.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is maintaining a belief despite new information that firmly contradicts it',choices:['Confirmation bias','Overconfidence','Hindsight bias','Belief perseverance'],ans:3,exp:'**Belief perseverance** means beliefs persist even after their basis is discredited. Confirmation bias is related but different: actively seeking and favoring evidence that supports what you already believe.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ occurs when people make a decision based on the way information is presented rather than on the facts themselves',choices:['Anchoring bias','Framing bias','Confirmation bias','Hindsight bias'],ans:1,exp:'**Framing bias**: a surgery with a "90% survival rate" is chosen more often than one with a "10% mortality rate," even though the two are identical. Hindsight bias is the feeling that you "knew it all along" after learning an outcome.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'The _____ is a standardized score (mean 100, standard deviation 15) derived from tests designed to assess human intelligence',choices:['mental age','g factor','intelligence quotient','emotional quotient'],ans:2,exp:'The **intelligence quotient (IQ)** was originally (mental age ÷ chronological age) × 100 and is now a deviation score, with about 95% of people scoring between 70 and 130. Mental age alone is the age level at which a person performs.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'The _____ states that an underlying general intelligence factor exists and forms the foundation from which all intellectual abilities arise',choices:['theory of multiple intelligences','general intelligence theory','triarchic theory of intelligence','theory of primary mental abilities'],ans:1,exp:'Spearman\'s **general intelligence (g) theory** came from the finding that scores on different cognitive tests are positively correlated. Gardner\'s multiple intelligences theory instead proposes several relatively independent intelligences.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is the ability to monitor one\'s own and other people\'s emotions, to discriminate between and label them appropriately, and to use emotional information to guide thinking and behavior',choices:['Emotional intelligence','Crystallized intelligence','Fluid intelligence','Practical intelligence'],ans:0,exp:'**Emotional intelligence** (Salovey and Mayer; popularized by Goleman) involves perceiving, understanding, using, and managing emotions. Practical intelligence is Sternberg\'s "street smarts," the ability to adapt to everyday environments.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is the capacity to think logically and solve problems in novel situations, independent of acquired knowledge',choices:['Crystallized intelligence','Emotional intelligence','Practical intelligence','Fluid intelligence'],ans:3,exp:'**Fluid intelligence** peaks in early adulthood and declines with age. Crystallized intelligence (accumulated knowledge and vocabulary) remains stable or grows into late adulthood.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is the ability to use learned knowledge and experience',choices:['Fluid intelligence','Crystallized intelligence','Emotional intelligence','Practical intelligence'],ans:1,exp:'**Crystallized intelligence** (e.g., vocabulary, general knowledge) is relatively preserved with aging. Fluid intelligence is novel reasoning, which declines with age.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'The _____ measure five factors of cognitive ability: fluid reasoning, knowledge, quantitative reasoning, visual-spatial processing, and working memory',choices:['Wechsler Adult Intelligence Scales','Stanford-Binet Intelligence Scales','Raven\'s Progressive Matrices','Minnesota Multiphasic Personality Inventories'],ans:1,exp:'The **Stanford-Binet Intelligence Scales** (5th edition) report five factor scores, each tested verbally and nonverbally. The WAIS instead reports four indices (verbal comprehension, perceptual reasoning, working memory, and processing speed).'},
  {s:'Emotion, Motivation & Stress',aamc:'7A',q:'In the nature versus nurture debate about how behavior develops, nature refers to _____ and nurture refers to _____',choices:['environment and experience / genes and hereditary factors','genes and hereditary factors / environment and experience','conscious choice / unconscious drives','hormones / neurotransmitters'],ans:1,exp:'**Nature** refers to genetic and inherited influences, and **nurture** refers to environmental influences such as upbringing, culture, and experience. Most traits reflect an interaction of both, which twin and adoption studies try to separate.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'In a _____, people believe their basic qualities, like their intelligence or talent, are simply fixed traits',choices:['growth mindset','fixed mindset','mental set','performance orientation'],ans:1,exp:'In Dweck\'s **fixed mindset**, failure is seen as proof of limited ability, so challenges are avoided. A growth mindset sees ability as developable, which promotes persistence after setbacks.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'In a _____, people believe that their most basic abilities can be developed through dedication and hard work',choices:['fixed mindset','mental set','growth mindset','performance orientation'],ans:2,exp:'A **growth mindset** (Dweck) treats effort and mistakes as part of learning. Mental set is a problem-solving term for sticking with a previously successful method, not a belief about ability.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'Galton\'s idea of hereditary genius holds that both mental and physical features are _____',choices:['learned','environmentally determined','randomly distributed','inherited'],ans:3,exp:'Francis Galton argued that intelligence is **inherited** like physical traits; this view fed the eugenics movement. He also pioneered twin studies and the phrase "nature versus nurture."'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is a measure of an individual\'s mental attainment, expressed as the age at which an average person reaches the same level of attainment',choices:['Intelligence quotient','Chronological age','Mental age','Percentile rank'],ans:2,exp:'**Mental age** was introduced by Binet; a 10-year-old who performs like an average 12-year-old has a mental age of 12. The original ratio IQ was mental age divided by chronological age, times 100.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'Thurstone\'s theory of _____ states that intelligent behavior emerges from seven independent factors',choices:['multiple intelligences','primary mental abilities','triarchic intelligence','general intelligence'],ans:1,exp:'Thurstone\'s **primary mental abilities** include verbal comprehension, word fluency, number, space, memory, perceptual speed, and reasoning. He rejected Spearman\'s single g factor, though his factors were later found to correlate with one another.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'The _____ describes analytical (componential), creative (experiential), and practical (contextual) intelligence',choices:['theory of multiple intelligences','two-factor theory of intelligence','triarchic theory of intelligence','theory of primary mental abilities'],ans:2,exp:'Sternberg\'s **triarchic theory** identifies three types of intelligence: analytical (book smarts), creative (novel problem solving), and practical (street smarts). Gardner\'s multiple intelligences theory lists eight or more domains, such as musical and bodily-kinesthetic intelligence.'},
  {s:'Personality, Development & Disorders',aamc:'6B',q:'_____ is a motor disorder caused by brain damage in which the individual has difficulty with the motor planning needed to perform tasks or movements on command, despite intact strength',choices:['Ataxia','Aphasia','Apraxia','Agnosia'],ans:2,exp:'**Apraxia** is a deficit in planning skilled movements (e.g., cannot pantomime brushing teeth on request), often after left parietal or frontal damage. Ataxia is uncoordinated movement, typically from cerebellar damage.'},
  {s:'Personality, Development & Disorders',aamc:'6B',q:'_____ is a speech disorder in which a child\'s brain has difficulty planning and coordinating the oral movements needed to combine sounds into syllables, syllables into words, and words into phrases',choices:['Dysarthria','Childhood-onset fluency disorder','Childhood apraxia of speech','Expressive aphasia'],ans:2,exp:'**Childhood apraxia of speech (CAS)** is a motor planning problem; the speech muscles themselves are not weak. Dysarthria, by contrast, is slurred speech caused by muscle weakness or poor muscle control.'},
  {s:'Personality, Development & Disorders',aamc:'6B',q:'_____ is a type of aphasia that results when brain damage is extensive enough to involve both Broca\'s and Wernicke\'s language areas',choices:['Conduction aphasia','Global aphasia','Transcortical motor aphasia','Anomic aphasia'],ans:1,exp:'**Global aphasia** impairs both comprehension and production, often after a large left middle cerebral artery stroke. Conduction aphasia results from damage to the arcuate fasciculus and mainly impairs repetition.'},
  {s:'Personality, Development & Disorders',aamc:'6B',q:'_____ is an acquired neurological disorder causing loss of the ability to communicate through writing, due either to motor dysfunction or to an inability to spell',choices:['Alexia','Dyscalculia','Ataxia','Agraphia'],ans:3,exp:'**Agraphia** (graph = write) is acquired loss of writing ability, for example after left angular gyrus damage. Alexia is the corresponding acquired loss of reading ability.'},
  {s:'Personality, Development & Disorders',aamc:'6B',q:'_____ is an acquired impairment of reading ability caused by brain damage',choices:['Agraphia','Dyscalculia','Alexia','Anomia'],ans:2,exp:'**Alexia** is reading loss acquired after brain injury (e.g., alexia without agraphia from a left occipital and splenium lesion). It differs from developmental dyslexia, a lifelong reading disorder that is not caused by acquired injury.'},
  {s:'Personality, Development & Disorders',aamc:'6B',q:'_____ is a form of aphasia in which the individual struggles to find the right words, especially names of objects',choices:['Alexia','Agraphia','Apraxia','Anomia'],ans:3,exp:'**Anomia** (word-finding difficulty) is present in nearly all aphasias and is the main deficit in anomic aphasia; speech is fluent but full of circumlocution. Apraxia is a motor planning disorder, not a language disorder.'},
  {s:'Biological Bases of Behavior',aamc:'7A',q:'The _____ is a thick band of nerve fibers that connects the left and right cerebral hemispheres',choices:['longitudinal fissure','corpus callosum','internal capsule','fornix'],ans:1,exp:'The **corpus callosum** is the largest commissure, a white-matter tract that lets the two hemispheres communicate. The longitudinal fissure is the groove that separates the hemispheres, and the fornix carries hippocampal output to the mammillary bodies.'},
  {s:'Biological Bases of Behavior',aamc:'7A',q:'Absence or surgical cutting of the _____ can result in split-brain syndrome, in which each hemisphere of the brain functions largely independently',choices:['longitudinal fissure','fornix','corpus callosum','internal capsule'],ans:2,exp:'After a **corpus callosotomy** (used for intractable epilepsy), an object flashed to the left visual field reaches only the right hemisphere, so the patient cannot name it (language is usually in the left hemisphere) but can pick it out with the left hand. Sperry and Gazzaniga studied these split-brain patients.'},
  {s:'Biological Bases of Behavior',aamc:'7A',q:'Each cerebral hemisphere controls movement and receives sensation from the _____ side of the body',choices:['ipsilateral','bilateral','contralateral','proximal'],ans:2,exp:'Motor and somatosensory pathways decussate (cross), so each hemisphere handles the **contralateral** side; for example, a left-hemisphere stroke causes right-sided weakness. Ipsilateral means the same side; the cerebellum is the main exception, controlling the ipsilateral body.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is the rhythm, stress, and intonation of speech, which conveys emotion and emphasis beyond the words themselves',choices:['Morphology','Prosody','Pragmatics','Syntax'],ans:1,exp:'**Prosody** lets the same sentence be a question or a statement depending on intonation; it relies heavily on the right hemisphere. Pragmatics is the use of language in social context (e.g., taking turns, indirect requests).'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'A _____ is a pattern that occurs systematically across all natural languages',choices:['dialect','language-specific rule','pidgin','linguistic universal'],ans:3,exp:'A **linguistic universal** is a feature found in all languages (e.g., all have nouns and verbs); Chomsky linked such universals to an innate universal grammar. A pidgin is a simplified contact language that develops between groups without a common language.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is the view that humans share a psychic unity of thought, and that language merely reflects human thought rather than shaping it',choices:['Linguistic relativity','Linguistic determinism','Nativism','Linguistic universalism'],ans:3,exp:'**Linguistic universalism** holds that thought is shared across humans and comes first, with language simply expressing it. Linguistic determinism and relativity reverse the direction, claiming that language shapes thought.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is the idea that language and its structures limit and determine human knowledge or thought',choices:['Linguistic universalism','Linguistic determinism','Linguistic relativity','Nativism'],ans:1,exp:'**Linguistic determinism** is the strong Whorfian claim that language controls thought. Linguistic relativity is the weaker claim that language merely influences thought, and it has more empirical support (e.g., color-naming studies).'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____, also known as _____, states that language completely determines thought',choices:['Linguistic relativity / the weak Whorfian hypothesis','Strong linguistic determinism / the strong Whorfian (Sapir-Whorf) hypothesis','Linguistic universalism / psychic unity','Nativist theory / the language acquisition device'],ans:1,exp:'**Strong linguistic determinism**, the strong form of the Whorfian (Sapir-Whorf) hypothesis, says language completely determines thought. The weak form, linguistic relativity, says language only influences thought.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'A _____ is a developmental window during which specific environmental input is required for normal development, whereas a _____ is a window during which input has its greatest effect but learning remains possible later',choices:['critical period / sensitive period','sensitive period / critical period','refractory period / latent period','incubation period / prodromal period'],ans:0,exp:'A **critical period** is an absolute window (e.g., input to both eyes for binocular vision; Genie\'s failure to fully acquire language). A **sensitive period** is an optimal but not absolute window (e.g., learning a second language without an accent).'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ describes the different ways that words can be rearranged to convey the same information, such as active versus passive voice',choices:['Morphological analysis','Pragmatic competence','Transformational grammar','Phonological awareness'],ans:2,exp:'Chomsky\'s **transformational grammar** distinguishes a sentence\'s deep structure (meaning) from its surface structure (word order); "The dog bit the man" and "The man was bitten by the dog" share a deep structure. Morphology is the structure of words built from morphemes.'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ refers to a person\'s mental vocabulary: the list of words they know, along with knowledge of each word\'s meaning and usage',choices:['Syntax','Phonology','Morphology','Lexicon'],ans:3,exp:'The **lexicon** is the mental dictionary of words and their meanings. Syntax is the set of rules for combining words into sentences.'},
  {s:'Personality, Development & Disorders',aamc:'6C',q:'_____ results from bilateral lesions of the medial temporal lobes (including the amygdalae) and causes hyperorality, hypersexuality, and loss of fear',choices:['Korsakoff syndrome','Capgras syndrome','Klüver-Bucy syndrome','Gerstmann syndrome'],ans:2,exp:'**Klüver-Bucy syndrome** shows the amygdala\'s role in fear and emotional evaluation: animals with these lesions approach threats placidly and mouth objects. Korsakoff syndrome is an amnestic disorder caused by thiamine deficiency.'},
  {s:'Emotion, Motivation & Stress',aamc:'6C',q:'The _____ states that the experience of emotion depends first on how a situation is cognitively appraised, an appraisal shaped by cultural and individual differences',choices:['James-Lange theory of emotion','Cannon-Bard theory of emotion','Schachter-Singer theory of emotion','Lazarus theory of emotion'],ans:3,exp:'In **Lazarus\'s cognitive appraisal theory**, thought (appraisal) comes first, and then emotion and arousal follow. In Schachter-Singer two-factor theory, physiological arousal comes first and is then cognitively labeled.'},
  {s:'Emotion, Motivation & Stress',aamc:'7A',q:'The _____ describes the relationship between arousal and performance: increased arousal improves performance, but only up to an optimal point, beyond which performance declines',choices:['Yerkes-Dodson law','Weber\'s law','drive-reduction theory','incentive theory'],ans:0,exp:'The **Yerkes-Dodson law** is an inverted U: moderate arousal is optimal, with lower optimal arousal for complex tasks and higher for simple ones. Weber\'s law concerns sensory just-noticeable differences, not arousal.'},
  {s:'Emotion, Motivation & Stress',aamc:'6C',q:'_____, such as grief, regret, and jealousy, have highly variable appearances and are composed of combinations of other emotions',choices:['Basic emotions','Moods','Temperaments','Complex emotions'],ans:3,exp:'**Complex emotions** blend basic emotions and cognition and lack a single universal facial expression. Basic emotions (e.g., fear, anger, joy) have universally recognized expressions.'},
  {s:'Emotion, Motivation & Stress',aamc:'6C',q:'Basic emotions, which include sadness, anger, fear, disgust, contempt, happiness, and surprise, are so called because they are associated with _____',choices:['learned cultural display rules','universally recognizable facial expressions','conscious cognitive appraisals','unique brain regions'],ans:1,exp:'Ekman found that basic emotions have **universally recognizable facial expressions** across cultures, which suggests an evolutionary basis. Cultural display rules govern when expressions are shown, not how they look.'},
  {s:'Emotion, Motivation & Stress',aamc:'6C',q:'The _____ to emotion describes emotional experience in terms of continuous dimensions such as arousal (high/low) and valence (positive/negative)',choices:['discrete emotion approach','appraisal approach','dimensional approach','evolutionary approach'],ans:2,exp:'The **dimensional approach** (e.g., Russell\'s circumplex model) places every emotion on axes of arousal and valence; excitement is high-arousal and positive. The discrete approach instead treats emotions as a small set of distinct categories.'},
  {s:'Emotion, Motivation & Stress',aamc:'6C',q:'_____ is the claim that there is a small number of core, distinct emotions',choices:['Dimensional emotion theory','Appraisal theory','Two-factor theory','Discrete emotion theory'],ans:3,exp:'**Discrete emotion theory** (Ekman, Izard) proposes a set of biologically based basic emotions, each with its own expression and physiology. Dimensional theory instead maps emotions continuously by arousal and valence.'},
  {s:'Emotion, Motivation & Stress',aamc:'6C',q:'_____ typically last longer than emotions and are less tied to a specific trigger',choices:['Startle responses','Moods','Facial expressions','Basic emotions'],ans:1,exp:'**Moods** are diffuse, longer-lasting affective states (hours to days), often without a clear cause. Emotions are brief, intense responses to a specific event.'},
  {s:'Emotion, Motivation & Stress',aamc:'6B',q:'The quicker you can shift your thinking from one dimension (e.g., the color of an object) to another (e.g., its shape), the greater your _____',choices:['working memory capacity','inhibitory control','cognitive flexibility','selective attention'],ans:2,exp:'**Cognitive flexibility** (set shifting) is an executive function of the prefrontal cortex, tested by the Wisconsin Card Sorting Test. Inhibitory control is suppressing a prepotent response, as in the Stroop task.'},
  {s:'Emotion, Motivation & Stress',aamc:'6C',q:'_____ refers to efforts to manage stress',choices:['Appraisal','Arousal','Rumination','Coping'],ans:3,exp:'**Coping** is the cognitive and behavioral effort to manage demands that exceed one\'s resources (problem-focused, emotion-focused, or meaning-focused). Appraisal is evaluating whether a situation is threatening (primary) and whether one can handle it (secondary).'},
  {s:'Emotion, Motivation & Stress',aamc:'6C',q:'_____ coping strategies generally involve confronting problems directly, making realistic appraisals of problems, recognizing and changing unhealthy emotional reactions, and trying to prevent adverse effects on the body',choices:['Maladaptive','Avoidant','Defensive','Adaptive'],ans:3,exp:'**Adaptive** coping (e.g., problem solving, exercise, seeking social support) reduces stress in the long run. Maladaptive coping (e.g., substance use, avoidance) gives short-term relief while the problem persists.'},
  {s:'Emotion, Motivation & Stress',aamc:'6C',q:'_____ coping strategies relieve symptoms temporarily but do not address the root cause of the stress',choices:['Adaptive','Problem-focused','Maladaptive','Meaning-focused'],ans:2,exp:'**Maladaptive** strategies such as avoidance, substance use, or denial can worsen stress over time. Problem-focused coping is adaptive because it tackles the stressor itself.'},
  {s:'Emotion, Motivation & Stress',aamc:'6C',q:'_____ coping involves searching for meaning in adversity and drawing on values, beliefs, and goals to change the meaning of, and one\'s response to, a stressful situation',choices:['Problem-focused','Emotion-focused','Avoidance-focused','Meaning-focused'],ans:3,exp:'**Meaning-focused** coping (Folkman) is especially useful for stressors that cannot be changed, such as chronic illness or bereavement. Problem-focused coping instead acts directly on a changeable stressor.'},
  {s:'Emotion, Motivation & Stress',aamc:'6C',q:'_____ is a coping response in which members of a minority group exert little effort toward socially valued goals (e.g., academic success) because they believe discrimination will block their success anyway',choices:['John Henryism','Low-effort syndrome','Stereotype threat','Acculturation'],ans:1,exp:'**Low-effort syndrome** is a minority coping response: if success seems blocked by discrimination, effort is withheld. John Henryism is the opposite, high-effort active coping with chronic stressors, which carries health costs such as hypertension.'},
  {s:'Biological Bases of Behavior',aamc:'7A',q:'The _____ (brainstem, cerebellum, and associated structures) regulates basic survival functions such as breathing, movement, rest, and feeding',choices:['cerebral cortex','prefrontal cortex','association cortex','old brain'],ans:3,exp:'The **old brain** comprises evolutionarily ancient structures (brainstem, cerebellum, and, in many textbooks, limbic and thalamic structures) shared with other vertebrates. The cerebral cortex (new brain) handles higher functions such as language and planning.'},
  {s:'Biological Bases of Behavior',aamc:'7A',q:'The _____ receives information from the sensory systems, the spinal cord, and other parts of the brain and uses it to coordinate and fine-tune motor movements',choices:['cerebellum','cerebrum','limbic system','brainstem'],ans:0,exp:'The **cerebellum** compares intended with actual movement to maintain balance, coordination, and motor learning; damage causes ipsilateral ataxia and intention tremor. Alcohol impairs it, which is the basis of field sobriety tests.'},
  {s:'Biological Bases of Behavior',aamc:'7A',q:'The _____ relays messages between the brain and the rest of the body and controls basic functions such as breathing, swallowing, heart rate, blood pressure, consciousness, and sleep-wake state',choices:['cerebellum','thalamus','brainstem','hypothalamus'],ans:2,exp:'The **brainstem** (midbrain, pons, medulla) houses cranial nerve nuclei, cardiorespiratory centers in the medulla, and the reticular activating system for arousal. The thalamus is a relay station for sensory input to the cortex, not a vital-function center.'},
  {s:'Biological Bases of Behavior',aamc:'7A',q:'The _____ is a network of neurons in the central core of the brainstem whose functions include motor control, sensory filtering, visceral control, and regulation of consciousness and arousal',choices:['substantia nigra','reticular formation','red nucleus','cerebellar vermis'],ans:1,exp:'The **reticular formation**, through its reticular activating system, keeps the cortex awake and alert; damage to it can cause coma. The substantia nigra is a dopaminergic midbrain nucleus that degenerates in Parkinson disease.'},
  {s:'Biological Bases of Behavior',aamc:'7A',q:'_____ arise from the brain and are distributed mainly to the head, neck, and facial regions',choices:['Spinal nerves','Cranial nerves','Dorsal root ganglia','Sympathetic chain ganglia'],ans:1,exp:'There are 12 pairs of **cranial nerves**, which emerge from the brain and brainstem (e.g., CN I for smell, CN II for vision). The vagus nerve (CN X) is the exception that extends to thoracic and abdominal organs.'},
  {s:'Biological Bases of Behavior',aamc:'7A',q:'_____ arise from the spinal cord and are distributed to the rest of the body, such as the skin, skeletal muscles, and blood vessels',choices:['Cranial nerves','Dorsal root ganglia','Spinal nerves','Sympathetic chain ganglia'],ans:2,exp:'There are 31 pairs of **spinal nerves**, each formed from a dorsal (sensory) root and a ventral (motor) root. Dorsal root ganglia contain only the cell bodies of sensory neurons; they are not the nerves themselves.'},
  {s:'Biological Bases of Behavior',aamc:'7A',q:'The _____ is a structure in the brainstem, above the medulla, that relays signals between the cerebrum and cerebellum and helps regulate sleep (including REM sleep) and breathing',choices:['medulla oblongata','midbrain','thalamus','pons'],ans:3,exp:'The **pons** ("bridge") connects the cortex to the cerebellum and contains REM-generating and respiratory centers. The medulla, below it, controls heart rate, blood pressure, and the basic rhythm of breathing.'},
  {s:'Biological Bases of Behavior',aamc:'7A',q:'_____ is a pseudoscience that measured bumps on the skull to predict mental traits',choices:['Physiognomy','Phrenology','Graphology','Neuropsychology'],ans:1,exp:'**Phrenology** (Franz Gall) was wrong about skull bumps, but it introduced the idea of localization of function. Physiognomy is a different pseudoscience that judged character from facial features.'},
  {s:'Biological Bases of Behavior',aamc:'7A',q:'Researchers often study people with brain lesions to establish the function of the damaged area. This research design is called a _____',choices:['twin study','longitudinal study','lesion study','cross-sectional study'],ans:2,exp:'A **lesion study** infers function from deficits, as with Phineas Gage (frontal lobe and personality) and patient H.M. (hippocampus and memory). It is correlational in humans because the lesions are not experimentally assigned.'},
  {s:'Biological Bases of Behavior',aamc:'7A',q:'A _____, also called a _____, uses computer-processed combinations of many X-ray measurements taken from different angles to produce cross-sectional images, allowing a view inside the body without cutting',choices:['MRI / NMR scan','CT scan / CAT scan','PET scan / SPECT scan','EEG / MEG'],ans:1,exp:'**Computed tomography (CT, or computed axial tomography, CAT)** combines many X-ray projections into cross-sectional images. It shows structure rather than function and involves ionizing radiation, unlike MRI.'},
  {s:'Biological Bases of Behavior',aamc:'7A',q:'_____ uses strong magnetic fields, magnetic field gradients, and radio waves to generate images of the body\'s organs',choices:['Computed tomography (CT)','Magnetic resonance imaging (MRI)','Positron emission tomography (PET)','Electroencephalography (EEG)'],ans:1,exp:'**MRI** detects radio signals from hydrogen nuclei aligned in a magnetic field, giving high-resolution soft-tissue images without ionizing radiation. CT uses X-rays instead and is faster but involves radiation exposure.'},
  {s:'Biological Bases of Behavior',aamc:'7A',q:'_____ is a test that detects electrical activity in the brain using small metal electrodes attached to the scalp',choices:['Electromyography (EMG)','Electroencephalography (EEG)','Magnetoencephalography (MEG)','Functional MRI (fMRI)'],ans:1,exp:'**EEG** has excellent temporal (millisecond) but poor spatial resolution and is used to study sleep stages and seizures. EMG instead records the electrical activity of muscles.'},
  {s:'Biological Bases of Behavior',aamc:'7A',q:'_____ measures the changes in blood oxygenation (the BOLD signal) that accompany brain activity',choices:['Computed tomography (CT)','Electroencephalography (EEG)','Positron emission tomography (PET)','Functional magnetic resonance imaging (fMRI)'],ans:3,exp:'**fMRI** detects the different magnetic properties of oxygenated and deoxygenated hemoglobin as active regions receive more blood. It has good spatial but limited temporal resolution; PET measures activity using an injected radioactive tracer instead.'},
  {s:'Biological Bases of Behavior',aamc:'7A',q:'A _____ scan uses an injected radioactive tracer to reveal how tissues and organs are functioning',choices:['CT','MRI','X-ray','PET'],ans:3,exp:'**Positron emission tomography (PET)** commonly uses ¹⁸F-fluorodeoxyglucose (FDG), which accumulates in metabolically active tissue. CT, MRI, and plain X-rays mainly show structure rather than function.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ are learned through experience with a person\'s environment',choices:['Inherited traits','Innate traits','Cardinal traits','Acquired traits'],ans:3,exp:'**Acquired traits** come from experience (e.g., an accent or learned fears). Inherited traits are passed on genetically; most characteristics reflect both.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ refers to biologically based, early-appearing tendencies (e.g., activity level and emotional reactivity) that shape how someone reacts to the world',choices:['Attachment style','Temperament','Self-concept','Locus of control'],ans:1,exp:'**Temperament** is visible in infancy (Thomas and Chess: easy, difficult, and slow-to-warm-up) and forms the foundation of later personality. Attachment style instead reflects the quality of early caregiver bonds.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ is the unique and relatively stable combination of patterns that influence a person\'s behavior, thought, motivation, and emotion',choices:['Temperament','Self-concept','Personality','Self-esteem'],ans:2,exp:'**Personality** is studied through psychoanalytic, humanistic, trait, social-cognitive, behaviorist, and biological perspectives. Temperament is the narrower, inborn emotional and behavioral style on which personality builds.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'Twin studies compare identical and fraternal twins to reveal the relative importance of _____ and _____ influences on traits, phenotypes, and disorders',choices:['conscious / unconscious','genetic / environmental','cognitive / emotional','maternal / paternal'],ans:1,exp:'Twin studies compare concordance in monozygotic (about 100% shared DNA) and dizygotic (about 50%) twins to estimate the relative **genetic** versus **environmental** contributions (heritability) to a trait. Higher concordance in identical twins points to a genetic contribution.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ is the study of heritable changes in gene expression that occur without changes in the DNA sequence itself',choices:['Behavioral genetics','Population genetics','Epigenetics','Mendelian genetics'],ans:2,exp:'**Epigenetics** includes DNA methylation (usually silencing) and histone acetylation (usually activating), which can be shaped by the environment, such as early-life stress. Behavioral genetics studies how genes and environment shape behavior, for example through twin studies.'},
  {s:'Emotion, Motivation & Stress',aamc:'7A',q:'_____ is the scientific study of animal behavior, usually under natural conditions, that views behavior as an evolutionarily adaptive trait',choices:['Comparative psychology','Behaviorism','Ethology','Behavioral genetics'],ans:2,exp:'**Ethology** (Lorenz, Tinbergen) studies behaviors such as imprinting and fixed-action patterns in natural settings. Comparative psychology studies animals, often in the lab, to draw conclusions about humans.'},
  {s:'Emotion, Motivation & Stress',aamc:'7A',q:'_____ is the study of animal behavior in order to learn about human behavior',choices:['Ethology','Comparative psychology','Sociobiology','Developmental psychology'],ans:1,exp:'**Comparative psychology** compares species (e.g., Harlow\'s monkeys on attachment) to understand human psychology. Ethology focuses on animal behavior for its own sake, in natural environments.'},
  {s:'Emotion, Motivation & Stress',aamc:'7A',q:'_____ behaviors do not have to be learned or practiced; an animal can perform them the first time it is exposed to the proper stimulus',choices:['Learned','Innate','Conditioned','Habituated'],ans:1,exp:'**Innate** behaviors (reflexes, fixed-action patterns) are genetically programmed. Conditioned behaviors require learning through classical or operant conditioning.'},
  {s:'Emotion, Motivation & Stress',aamc:'7A',q:'A _____ is a sequence of innate, coordinated movements that, once triggered, runs to completion without interruption; it is like a reflex but more complex',choices:['conditioned response','habituated response','operant behavior','fixed-action pattern'],ans:3,exp:'A **fixed-action pattern** is triggered by a sign stimulus; for example, a goose rolling a displaced egg back to its nest finishes the motion even if the egg is removed. A conditioned response, by contrast, is learned.'},
  {s:'Emotion, Motivation & Stress',aamc:'7A',q:'_____ is behavior that is not directly observable by others, such as thinking',choices:['Overt behavior','Innate behavior','Operant behavior','Covert behavior'],ans:3,exp:'**Covert behavior** (thoughts, feelings, imagery) is internal and must be inferred or self-reported. Overt behavior is externally visible action.'},
  {s:'Emotion, Motivation & Stress',aamc:'7A',q:'_____ is a state of lacking any motivation to engage in an activity',choices:['Amotivation','Anhedonia','Extrinsic motivation','Intrinsic motivation'],ans:0,exp:'In self-determination theory, **amotivation** lies at the far end of the continuum from intrinsic motivation: there is no intention to act. Anhedonia is the inability to feel pleasure, a core symptom of major depressive disorder.'},
  {s:'Emotion, Motivation & Stress',aamc:'7A',q:'In order, the four phases of the sexual response cycle are _____, _____, _____, and _____',choices:['Plateau / Excitement / Orgasm / Resolution','Excitement / Plateau / Orgasm / Resolution','Excitement / Orgasm / Plateau / Resolution','Desire / Excitement / Orgasm / Refractory'],ans:1,exp:'Masters and Johnson\'s four-phase cycle is **excitement → plateau → orgasm → resolution**. Men (but not most women) have a refractory period during resolution.'},
  {s:'Emotion, Motivation & Stress',aamc:'7A',q:'_____ is released after orgasm and is associated with sexual satiation and the refractory period',choices:['Dopamine','Testosterone','Estrogen','Prolactin'],ans:3,exp:'Post-orgasmic **prolactin** release is linked to sexual satiety and helps produce the refractory period. Dopamine instead drives sexual desire and the anticipation of reward.'},
  {s:'Emotion, Motivation & Stress',aamc:'7A',q:'_____ are endogenous opioids that produce feelings of euphoria and pain relief and are released during sexual activity and orgasm',choices:['Gonadotropins','Endorphins','Corticosteroids','Catecholamines'],ans:1,exp:'**Endorphins** bind μ-opioid receptors and are also released during intense exercise ("runner\'s high"). Corticosteroids such as cortisol are stress hormones and do not produce euphoria.'},
  {s:'Emotion, Motivation & Stress',aamc:'7A',q:'_____ is released after orgasm and promotes bonding and feelings of connectedness between sexual partners',choices:['Prolactin','Cortisol','Melatonin','Oxytocin'],ans:3,exp:'**Oxytocin**, from the posterior pituitary (made in the hypothalamus), promotes pair bonding, trust, and maternal bonding, and also triggers milk letdown and uterine contractions. Prolactin, from the anterior pituitary, is linked to sexual satiation.'},
  {s:'Emotion, Motivation & Stress',aamc:'7A',q:'The _____ states that behavior is best predicted by intentions, which are shaped by attitudes toward the behavior, subjective norms, and perceived behavioral control',choices:['elaboration likelihood model','attitude-to-behavior process model','prototype willingness model','theory of planned behavior'],ans:3,exp:'In Ajzen\'s **theory of planned behavior**, attitudes, subjective norms, and perceived behavioral control lead to intention, and intention leads to behavior. The prototype willingness model instead explains impulsive, unplanned risk behaviors.'},
  {s:'Emotion, Motivation & Stress',aamc:'7A',q:'The _____ states that behavior stems from an individual\'s perception of an attitude object and of the situation in which the object is encountered',choices:['theory of planned behavior','prototype willingness model','attitude-to-behavior process model','elaboration likelihood model'],ans:2,exp:'In Fazio\'s **attitude-to-behavior process model**, an event activates an attitude, which combines with knowledge of situational norms to shape perception of the event and then behavior. It explains spontaneous behavior, whereas the theory of planned behavior explains deliberate behavior.'},
  {s:'Emotion, Motivation & Stress',aamc:'7A',q:'The _____ holds that how attractive or unattractive a person finds the typical "risk prototype" (e.g., the typical smoker) shapes their willingness to engage in a risky behavior',choices:['prototype willingness model','theory of planned behavior','attitude-to-behavior process model','health belief model'],ans:0,exp:'The **prototype willingness model** explains adolescent risk taking as willingness in the moment rather than planned intention. The theory of planned behavior assumes deliberate intentions.'},
  {s:'Emotion, Motivation & Stress',aamc:'7A',q:'The _____ involves making a small request first in order to get a person to later agree to a bigger request',choices:['door-in-the-face technique','foot-in-the-door technique','lowball technique','that\'s-not-all technique'],ans:1,exp:'The **foot-in-the-door technique** works through consistency and self-perception: having said yes once, the person sees themselves as helpful. The door-in-the-face technique does the reverse, starting with a large request that is refused.'},
  {s:'Emotion, Motivation & Stress',aamc:'7A',q:'_____ is the tendency to value an outcome more highly than its objective worth when one had to put effort into achieving it',choices:['Overjustification effect','Endowment effect','Effort justification','Self-serving bias'],ans:2,exp:'**Effort justification** is a form of cognitive dissonance reduction ("I suffered for it, so it must be worth it"), as in harsh initiations that increase group loyalty. The endowment effect is valuing something more simply because you own it.'},
  {s:'Emotion, Motivation & Stress',aamc:'7A',q:'When you refuse a large request and then agree to a subsequent, smaller request, this is called the _____',choices:['foot-in-the-door technique','lowball technique','door-in-the-face technique','that\'s-not-all technique'],ans:2,exp:'The **door-in-the-face technique** relies on reciprocity: the requester "concedes," so you concede too. The foot-in-the-door technique starts small and then escalates.'},
  {s:'Emotion, Motivation & Stress',aamc:'7A',q:'_____ is the mental discomfort experienced by a person who holds two or more contradictory beliefs, ideas, or values, or whose behavior conflicts with their beliefs',choices:['Role strain','Belief perseverance','Learned helplessness','Cognitive dissonance'],ans:3,exp:'**Cognitive dissonance** (Festinger) motivates people to restore consistency, often by changing an attitude to match their behavior. Belief perseverance is holding onto a belief despite contradicting evidence.'},
  {s:'Emotion, Motivation & Stress',aamc:'7A',q:'The four ways people reduce cognitive dissonance are _____, _____, _____, and _____',choices:['Projection / Displacement / Sublimation / Reaction formation','Compliance / Identification / Internalization / Obedience','Changing attitudes / Adding cognitions / Altering importance / Reducing choice','Rote rehearsal / Chunking / Elaboration / Spacing'],ans:2,exp:'Dissonance is reduced by **changing the attitude or behavior, adding consonant cognitions that justify it, trivializing (altering the importance of) the conflicting cognitions, or reducing perceived choice or responsibility**. The defense mechanisms listed among the distractors protect the ego from anxiety rather than resolving inconsistent cognitions.'},
  {s:'Emotion, Motivation & Stress',aamc:'7A',q:'The _____ states that behavior depends more on the demands of a particular situation than on stable personality traits',choices:['trait approach','psychodynamic approach','humanistic approach','situational approach'],ans:3,exp:'The **situational approach** (e.g., Mischel\'s critique of traits) predicts that people act differently across situations. The trait approach assumes stable dispositions produce consistent behavior; the modern interactionist view combines the two.'},
  {s:'Social Psychology & Society',aamc:'7B',q:'_____ studies how individuals act, think, and feel in the context of other people and society',choices:['Cognitive psychology','Social psychology','Developmental psychology','Personality psychology'],ans:1,exp:'**Social psychology** covers topics such as conformity, attribution, attitudes, and group behavior. Personality psychology instead focuses on stable individual differences across situations.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ is a defense mechanism in which individuals attribute characteristics they find unacceptable in themselves to another person',choices:['Displacement','Projection','Reaction formation','Rationalization'],ans:1,exp:'In **projection**, a person who is hostile accuses others of being hostile; the Rorschach and TAT are called "projective" tests for this reason. Displacement redirects an impulse toward a safer target (e.g., yelling at the dog after a bad day at work).'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ is a defense mechanism in which a person who sees their true feelings or desires as socially unacceptable tries to convince themselves or others that the opposite is true, often in an exaggerated way',choices:['Projection','Sublimation','Reaction formation','Displacement'],ans:2,exp:'**Reaction formation** is expressing the opposite of an unacceptable impulse, such as being overly sweet to someone you dislike. Projection instead attributes your own unacceptable feelings to someone else.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ is a defense mechanism in which a person reverts to behaviors typical of a much younger stage of life',choices:['Fixation','Displacement','Repression','Regression'],ans:3,exp:'**Regression** (e.g., an older child resuming bedwetting when a sibling is born) is a temporary retreat under stress. Fixation, in Freud\'s theory, is being stuck at a psychosexual stage because of unresolved conflict.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ is a mature defense mechanism in which socially unacceptable impulses are transformed into socially acceptable actions or behavior',choices:['Displacement','Reaction formation','Rationalization','Sublimation'],ans:3,exp:'**Sublimation** channels aggression into boxing or surgery, for example; it is the only classic defense mechanism generally considered mature. Displacement redirects the impulse to a safer target without making it socially productive.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'A _____, also called a parapraxis, is an error in speech, memory, or action believed to reveal an unconscious wish or thought',choices:['tip-of-the-tongue state','Korsakoff confabulation','malapropism','Freudian slip'],ans:3,exp:'A **Freudian slip** (e.g., calling your partner by an ex\'s name) was seen by Freud as a window into the unconscious. A tip-of-the-tongue state is a retrieval failure in which you know a word but cannot quite produce it.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'According to Hans Eysenck, _____ seek excitement and social activity in an effort to raise their arousal level, whereas _____ tend to avoid social situations to keep arousal to a minimum',choices:['introverts / extraverts','extraverts / introverts','neurotic individuals / emotionally stable individuals','psychotic individuals / extraverts'],ans:1,exp:'Eysenck proposed that **extraverts** have low baseline cortical arousal, so they seek stimulation, while **introverts** have high baseline arousal, so they avoid stimulating social situations. His PEN model has three dimensions: psychoticism, extraversion, and neuroticism.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'In Jeffrey Gray\'s _____ of personality, a behavioral approach system (BAS) regulates appetitive motives (moving toward something desired), and a behavioral inhibition system (BIS) regulates aversive motives (moving away from something unpleasant)',choices:['social-cognitive theory','psychoanalytic theory','biopsychological theory','humanistic theory'],ans:2,exp:'Gray\'s **biopsychological theory** (reinforcement sensitivity theory) ties personality to brain systems for reward and punishment: high BAS sensitivity relates to impulsivity and extraversion, and high BIS sensitivity to anxiety. Social-cognitive theory instead stresses reciprocal interactions among person, behavior, and environment.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ is a personality trait defined as social dominance or interpersonal power and a desire to make an impact on others',choices:['Social closeness','Social potency','Social desirability','Self-efficacy'],ans:1,exp:'**Social potency** is a facet of extraversion (positive emotionality) that reflects assertiveness and leadership; it is relatively heritable. Social closeness is the warm, affiliative facet: enjoying intimacy and close relationships.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'The _____ is associated with novelty seeking and thrill seeking, as well as with attention-deficit/hyperactivity disorder (ADHD) and addictive and risky behavior',choices:['serotonin transporter (5-HTTLPR) gene','dopamine receptor D4 (DRD4) gene','monoamine oxidase A (MAOA) gene','apolipoprotein E (APOE) gene'],ans:1,exp:'Variants of the **DRD4** gene (e.g., the 7-repeat allele) are linked to novelty seeking and ADHD through dopamine reward signaling. The MAOA "warrior gene" is linked to aggression, and APOE ε4 to Alzheimer disease risk.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ traits of personality are obvious and easily identified by other people, whereas _____ traits are less visible and underlie several different aspects of behavior',choices:['Source / surface','Surface / source','Cardinal / central','Central / secondary'],ans:1,exp:'In Cattell\'s model, **surface traits** are clusters of observable behavior, and **source traits** are the deeper underlying factors (16 in the 16PF) that give rise to them. Cardinal, central, and secondary traits belong to Allport\'s trait hierarchy instead.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'The _____ is an introspective self-report questionnaire that sorts people by differing psychological preferences in how they perceive the world and make decisions',choices:['Minnesota Multiphasic Personality Inventory','Thematic Apperception Test','Myers-Briggs Type Indicator','Rorschach inkblot test'],ans:2,exp:'The **Myers-Briggs Type Indicator (MBTI)** is based on Jung\'s types and yields 16 types (e.g., E/I, S/N, T/F, J/P), though it has weak reliability and validity. The TAT and Rorschach are projective tests, not self-report questionnaires.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ is a defense mechanism involving refusal to accept reality, acting as if a painful event, thought, or feeling did not exist',choices:['Repression','Denial','Suppression','Rationalization'],ans:1,exp:'In **denial**, a person refuses to acknowledge an external reality (e.g., insisting a diagnosis is wrong). Repression instead unconsciously blocks internal thoughts or memories from awareness.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ behaviors involve expressing aggression indirectly (e.g., procrastination, sullenness, or deliberate inefficiency) rather than directly',choices:['Overtly hostile','Assertive','Passive-aggressive','Instrumentally aggressive'],ans:2,exp:'**Passive-aggressive** behavior expresses hostility covertly, such as "forgetting" a task you resent. Assertive behavior expresses needs directly and respectfully, without hostility.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ is a defense mechanism in which reasoning is used to avoid confronting an unconscious conflict and its associated emotional stress; thinking is used to avoid feeling',choices:['Rationalization','Sublimation','Denial','Intellectualization'],ans:3,exp:'In **intellectualization**, a patient may discuss the statistics of their cancer in detached clinical terms to avoid fear. Rationalization instead creates a self-serving justification for a behavior after the fact.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ is a defense mechanism in which unacceptable behaviors or feelings are justified with seemingly rational or logical explanations to avoid the true explanation',choices:['Intellectualization','Rationalization','Projection','Reaction formation'],ans:1,exp:'**Rationalization** includes "sour grapes" thinking (e.g., "I didn\'t want that job anyway"). Intellectualization focuses on abstract facts to avoid emotion, rather than inventing excuses.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ is a defense mechanism that involves unconsciously keeping certain thoughts, feelings, or urges out of conscious awareness',choices:['Suppression','Denial','Displacement','Repression'],ans:3,exp:'**Repression** is unconscious and, for Freud, the basis of all other defense mechanisms. Suppression is the conscious, deliberate decision to put a thought aside and is considered a mature coping strategy.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ involves consciously pushing away unwanted impulses or thoughts, whereas _____ involves unconsciously keeping them out of awareness',choices:['Repression / suppression','Suppression / repression','Sublimation / displacement','Denial / projection'],ans:1,exp:'**Suppression** is a mature, conscious decision to set aside distressing thoughts; **repression** is an unconscious defense mechanism that keeps threatening thoughts out of awareness. Mnemonic: you choose to suppress, but you never know you have repressed.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ is a defense mechanism that involves redirecting frustrations, feelings, and impulses onto people or objects that are less threatening',choices:['Projection','Sublimation','Regression','Displacement'],ans:3,exp:'In **displacement**, someone angry at their boss comes home and kicks the dog. Sublimation redirects the impulse into a socially valued activity instead.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'In Freudian psychoanalysis, the _____ is the instinctive seeking of pleasure and avoidance of pain to satisfy biological and psychological needs',choices:['reality principle','repetition compulsion','death drive','pleasure principle'],ans:3,exp:'The id operates on the **pleasure principle**, demanding immediate gratification. The ego operates on the reality principle, delaying gratification until it can be satisfied appropriately.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'In Freudian psychoanalysis, the _____ is the mind\'s ability to assess the external world and act on it accordingly, rather than acting only to gain immediate pleasure',choices:['pleasure principle','reality principle','repetition compulsion','death drive'],ans:1,exp:'The ego follows the **reality principle**, mediating between the id\'s demands, the superego\'s morals, and external reality. The pleasure principle drives the id\'s demand for immediate gratification.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'Freud identified two drives that both coincide and conflict within individuals: Eros is the drive of _____, and Thanatos is the drive of _____',choices:['death / life','pleasure / reality','life / death','reality / pleasure'],ans:2,exp:'Freud\'s Eros is the **life** instinct (self-preservation, sex, love), and Thanatos is the **death** instinct (aggression, self-destruction). Libido is the energy of Eros.'},
  {s:'Personality, Development & Disorders',aamc:'6C',q:'_____ is stress that is neither positive nor negative, arising from events that have no meaningful impact on a person',choices:['Eustress','Neustress','Distress','Acute stress'],ans:1,exp:'**Neustress** is neutral stress, such as hearing about a disaster far away that does not affect you. Eustress is positive stress (e.g., a promotion), and distress is negative stress.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ are a group of DSM-5-TR disorders in which the development of the central nervous system is disturbed, typically with onset in early childhood',choices:['Neurodevelopmental disorders','Neurocognitive disorders','Personality disorders','Dissociative disorders'],ans:0,exp:'**Neurodevelopmental disorders** include autism spectrum disorder, ADHD, intellectual developmental disorder, and specific learning disorders. Neurocognitive disorders, by contrast, involve decline from a previously attained level of functioning.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ are characterized by acquired decline from a previous level of functioning in one or more cognitive domains',choices:['Neurodevelopmental disorders','Neurocognitive disorders','Dissociative disorders','Somatic symptom disorders'],ans:1,exp:'**Neurocognitive disorders** in DSM-5-TR include delirium and major or mild neurocognitive disorder (formerly "dementia"), for example due to Alzheimer disease. The key word is "acquired," which contrasts with neurodevelopmental disorders that are present from early development.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ involve problems with the quality, timing, and amount of sleep that cause daytime distress and impaired functioning',choices:['Somatic symptom disorders','Sleep-wake disorders','Mood disorders','Dissociative disorders'],ans:1,exp:'DSM-5-TR **sleep-wake disorders** include insomnia disorder, narcolepsy, breathing-related sleep disorders (e.g., obstructive sleep apnea), circadian rhythm disorders, and parasomnias. Sleep disturbance is also a symptom of mood disorders, but in those disorders it is not the primary problem.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ involve the repeated passage of urine or feces at inappropriate times or places',choices:['Feeding and eating disorders','Elimination disorders','Somatic symptom disorders','Neurodevelopmental disorders'],ans:1,exp:'DSM-5-TR **elimination disorders** are enuresis (urine, diagnosed at age 5 or older) and encopresis (feces, age 4 or older). Feeding and eating disorders (e.g., pica, anorexia) concern intake, not elimination.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ refers to a problem during any phase of the sexual response cycle that prevents the individual or couple from experiencing satisfaction from sexual activity',choices:['Gender dysphoria','Paraphilic disorder','Somatic symptom disorder','Sexual dysfunction'],ans:3,exp:'**Sexual dysfunctions** (e.g., erectile disorder, female sexual interest/arousal disorder, premature ejaculation) map onto phases of the response cycle. Paraphilic disorders concern atypical sources of sexual arousal, not impaired response.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ is clinically significant distress caused by incongruence between a person\'s experienced gender and their assigned gender',choices:['Sexual dysfunction','Paraphilic disorder','Body dysmorphic disorder','Gender dysphoria'],ans:3,exp:'In DSM-5-TR, **gender dysphoria** centers on the distress, not on gender nonconformity or identity itself. Body dysmorphic disorder is preoccupation with a perceived flaw in appearance.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ involve recurrent, intense sexually arousing fantasies, urges, or behaviors involving atypical targets (e.g., nonconsenting persons or inanimate objects) that cause distress or impairment, or that have harmed or risk harming others',choices:['Sexual dysfunctions','Paraphilic disorders','Impulse-control disorders','Somatic symptom disorders'],ans:1,exp:'DSM-5-TR distinguishes a paraphilia (an atypical interest) from a **paraphilic disorder**, which also causes distress, impairment, or harm to others (e.g., voyeuristic or pedophilic disorder). Sexual dysfunctions involve impaired sexual response rather than atypical arousal.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'In medicine, a _____ is an early sign or symptom that indicates the onset of a disease before more diagnostically specific signs and symptoms develop',choices:['prognosis','syndrome','sequela','prodrome'],ans:3,exp:'A **prodrome** precedes the full illness, such as the prodromal phase of schizophrenia (social withdrawal, odd beliefs) or the aura before a migraine. A sequela is a condition that follows as a consequence of a disease.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ is a mental disorder in which a person deliberately falsifies or induces symptoms of physical or mental illness even without obvious external rewards',choices:['Malingering','Factitious disorder','Conversion disorder','Illness anxiety disorder'],ans:1,exp:'In **factitious disorder** (formerly Munchausen syndrome), the motive is internal, such as assuming the sick role. Malingering is also deliberate faking, but for external gain (e.g., money, avoiding work), and it is not a mental disorder.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ is a personality disorder characterized by a long-term pattern of disregard for, or violation of, the rights of others',choices:['Narcissistic personality disorder','Borderline personality disorder','Antisocial personality disorder','Paranoid personality disorder'],ans:2,exp:'**Antisocial personality disorder** (Cluster B) requires age 18 or older with evidence of conduct disorder before age 15, and is more common in men. Narcissistic personality disorder involves grandiosity and need for admiration rather than rule breaking.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ is a personality disorder marked by intense, unstable emotions, highly impulsive behaviors, an unstable self-image, and a history of unstable relationships',choices:['Histrionic personality disorder','Antisocial personality disorder','Narcissistic personality disorder','Borderline personality disorder'],ans:3,exp:'**Borderline personality disorder** (Cluster B) features fear of abandonment, splitting (all-good or all-bad views of others), and self-harm; dialectical behavior therapy is the main treatment. Histrionic personality disorder involves attention seeking without the same identity disturbance and self-harm.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ is a personality disorder characterized by a pattern of excessive emotionality and attention seeking, beginning by early adulthood, including inappropriately seductive behavior and an excessive need for approval',choices:['Narcissistic personality disorder','Borderline personality disorder','Dependent personality disorder','Histrionic personality disorder'],ans:3,exp:'**Histrionic personality disorder** (Cluster B) involves dramatic, shallow emotion and discomfort when not the center of attention. Narcissistic personality disorder seeks admiration from a sense of superiority rather than attention for its own sake.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ is a personality disorder with a long-term pattern of grandiosity (exaggerated self-importance), excessive need for admiration, and lack of empathy',choices:['Histrionic personality disorder','Antisocial personality disorder','Narcissistic personality disorder','Paranoid personality disorder'],ans:2,exp:'**Narcissistic personality disorder** (Cluster B) masks a fragile self-esteem that reacts strongly to criticism. Antisocial personality disorder also lacks empathy, but it is defined by violating others\' rights and laws.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ is characterized by extreme social inhibition, feelings of inadequacy, and hypersensitivity to criticism and rejection, despite a desire for relationships',choices:['Schizoid personality disorder','Dependent personality disorder','Paranoid personality disorder','Avoidant personality disorder'],ans:3,exp:'**Avoidant personality disorder** (Cluster C) involves wanting relationships but fearing rejection. Schizoid personality disorder (Cluster A) involves genuine indifference to relationships.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ is an anxious (Cluster C) personality disorder characterized by an excessive need to be taken care of, leading to submissive, clinging behavior and discomfort when alone',choices:['Avoidant personality disorder','Borderline personality disorder','Histrionic personality disorder','Dependent personality disorder'],ans:3,exp:'**Dependent personality disorder** includes difficulty making everyday decisions without reassurance and urgently seeking a new relationship when one ends. Borderline personality disorder also fears abandonment, but it features unstable, intense relationships and impulsivity rather than submissiveness.'},
  {s:'Personality, Development & Disorders',aamc:'6B',q:'_____ is a potentially serious sleep disorder in which breathing repeatedly stops and starts during sleep',choices:['Narcolepsy','Insomnia','Restless legs syndrome','Sleep apnea'],ans:3,exp:'Obstructive **sleep apnea** (airway collapse, linked to obesity) causes loud snoring, daytime sleepiness, and hypertension; central sleep apnea results from absent respiratory drive. Narcolepsy instead involves sudden REM intrusions and cataplexy.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ is a dementia associated with abnormal alpha-synuclein deposits in the cortex, typically with visual hallucinations, fluctuating cognition, and parkinsonism',choices:['Alzheimer disease','Frontotemporal dementia','Vascular dementia','Dementia with Lewy bodies'],ans:3,exp:'**Dementia with Lewy bodies** shares alpha-synuclein pathology with Parkinson disease (where Lewy bodies sit mainly in the substantia nigra), and patients are very sensitive to antipsychotics. Alzheimer disease instead involves β-amyloid plaques and tau neurofibrillary tangles.'},
  {s:'Personality, Development & Disorders',aamc:'7A',q:'_____ are habitual, exaggerated, or irrational thought patterns through which our mind convinces us of something that is not really true',choices:['Defense mechanisms','Delusions','Cognitive distortions','Heuristics'],ans:2,exp:'**Cognitive distortions** (e.g., catastrophizing, all-or-nothing thinking, overgeneralization) are targeted by CBT, as described by Beck. Delusions are fixed false beliefs that persist despite clear evidence, as in psychotic disorders, and are far more severe.'},
  {s:'Social Psychology & Society',aamc:'7B',q:'_____ occurs when a person conforms to a group to gain knowledge or because they believe the others are "right"',choices:['Normative social influence','Informational social influence','Social facilitation','Groupthink'],ans:1,exp:'**Informational social influence** is strongest when a situation is ambiguous (e.g., Sherif\'s autokinetic effect study) and often leads to internalization. Normative social influence is conforming to be liked or to avoid rejection.'},
  {s:'Social Psychology & Society',aamc:'7B',q:'_____ occurs when a person conforms with a group in order to be liked and accepted by them',choices:['Informational social influence','Normative social influence','Social facilitation','Deindividuation'],ans:1,exp:'**Normative social influence** drove conformity in Asch\'s line studies, where the matching line was obvious. It usually produces public compliance without private acceptance.'},
  {s:'Social Psychology & Society',aamc:'7B',q:'_____ is the shallowest level of conformity, in which a person changes their public behavior but not their private beliefs',choices:['Identification','Internalization','Compliance','Obedience'],ans:2,exp:'In Kelman\'s three levels, **compliance** is going along publicly to gain reward or avoid punishment while privately disagreeing. Obedience is different: it is following a direct command from an authority figure.'},
  {s:'Social Psychology & Society',aamc:'7B',q:'_____ is the middle level of conformity, in which a person changes their public behavior and private beliefs, but only while they are in the presence of the group',choices:['Identification','Compliance','Internalization','Obedience'],ans:0,exp:'**Identification** occurs because a person values their relationship with the group, so the change fades when they leave it. Internalization is a lasting change because the person truly accepts the new view.'},
  {s:'Social Psychology & Society',aamc:'7B',q:'_____ is the deepest level of conformity, in which a person changes both their public behavior and private beliefs in a lasting way, often as a result of informational social influence',choices:['Compliance','Identification','Obedience','Internalization'],ans:3,exp:'**Internalization** means the person has truly adopted the group\'s view, so it persists even without the group. Compliance changes only public behavior.'},
  {s:'Social Psychology & Society',aamc:'7B',q:'_____ proposes that deviance is socially constructed through others\' reactions rather than the act itself, so no behavior is inherently deviant',choices:['Strain theory','Differential association theory','Labeling theory','Social control theory'],ans:2,exp:'**Labeling theory** (a symbolic interactionist view) argues that being labeled "deviant" can become a self-fulfilling identity. Differential association theory says deviance is learned through interaction with others who engage in it.'},
  {s:'Social Psychology & Society',aamc:'7B',q:'_____ is minor deviance with no serious consequences, after which the person is not labeled as a deviant',choices:['Secondary deviance','Primary deviance','Tertiary deviance','Positive deviance'],ans:1,exp:'**Primary deviance** (e.g., occasional jaywalking) does not change a person\'s self-concept. Secondary deviance occurs when a stigmatizing label leads the person to adopt a deviant identity.'},
  {s:'Social Psychology & Society',aamc:'7B',q:'_____ has serious consequences: a severe negative social reaction produces a stigmatizing label, which leads to more deviant behavior',choices:['Primary deviance','Tertiary deviance','Secondary deviance','Positive deviance'],ans:2,exp:'In **secondary deviance**, a person accepts the "deviant" label as part of their identity (Lemert), and the label becomes self-fulfilling. Tertiary deviance is the later stage of rejecting the label and reclaiming the behavior as normal.'},
  {s:'Emotion, Motivation & Stress',aamc:'7B',q:'_____ refers to relatively spontaneous, short-lived group behavior that does not follow established social norms but is shaped by the issue at hand',choices:['Social movements','Collective behavior','Social institutions','Group polarization'],ans:1,exp:'**Collective behavior** includes fads, mass hysteria, and riots. Social movements differ because they are organized, sustained, and goal-directed.'},
  {s:'Emotion, Motivation & Stress',aamc:'7B',q:'A _____ is a type of collective behavior in which a group of people enthusiastically follows an impulse for a limited period',choices:['mob','riot','panic','fad'],ans:3,exp:'A **fad** (e.g., a viral dance) is short-lived and usually harmless. A mob is an emotionally charged crowd intent on a specific, often violent, purpose.'},
  {s:'Emotion, Motivation & Stress',aamc:'7B',q:'_____ is a type of collective behavior in which illusions of threats, whether real or imaginary, spread through a population as a result of rumors and fear',choices:['Fad','Riot','Mob behavior','Mass hysteria'],ans:3,exp:'**Mass hysteria** can produce shared physical symptoms with no organic cause (e.g., outbreaks of fainting or twitching that spread through a school). A riot, by contrast, is violent crowd behavior driven by perceived injustice.'},
  {s:'Emotion, Motivation & Stress',aamc:'7B',q:'A _____ is a violent form of crowd behavior that results from feelings of injustice or a sense that needs have been ignored',choices:['fad','flash mob','craze','riot'],ans:3,exp:'A **riot** involves deindividuation, in which anonymity in a crowd lowers self-restraint. A fad or craze is a harmless, short-lived enthusiasm.'},
  {s:'Cognition, Learning & Memory',aamc:'7C',q:'Stimulus _____ occurs when a person responds to a new stimulus in the same way that they respond to a similar, conditioned stimulus',choices:['discrimination','acquisition','generalization','extinction'],ans:2,exp:'In stimulus **generalization**, Little Albert, conditioned to fear a white rat, also feared other white, furry objects. Stimulus discrimination is the opposite: responding only to the specific conditioned stimulus.'},
  {s:'Cognition, Learning & Memory',aamc:'7C',q:'_____ refers to the reappearance, after a delay, of a conditioned response that had been extinguished',choices:['Extinction burst','Stimulus generalization','Second-order conditioning','Spontaneous recovery'],ans:3,exp:'**Spontaneous recovery** shows that extinction suppresses rather than erases learning. An extinction burst is a brief increase in a behavior right after reinforcement stops, before extinction occurs.'},
  {s:'Cognition, Learning & Memory',aamc:'7C',q:'When reinforcement for a behavior stops, the behavior often temporarily increases in frequency or intensity before it declines. This is known as _____',choices:['spontaneous recovery','extinction burst','instinctive drift','learned helplessness'],ans:1,exp:'An **extinction burst** is like pressing a broken elevator button harder and faster. Spontaneous recovery is the return of an extinguished response after a delay.'},
  {s:'Cognition, Learning & Memory',aamc:'7C',q:'_____ pairs an unwanted behavior with something unpleasant to stop that behavior, as when disulfiram makes drinking alcohol cause nausea',choices:['Systematic desensitization','Flooding','Aversive conditioning','Token economy'],ans:2,exp:'**Aversive conditioning** is a classical conditioning therapy that attaches a negative response to a previously pleasurable stimulus. Systematic desensitization does the opposite, replacing fear with relaxation.'},
  {s:'Cognition, Learning & Memory',aamc:'7C',q:'_____ is a behavioral therapy for phobias and anxiety disorders in which the person learns a relaxation technique and is then gradually exposed to a hierarchy of anxiety-producing stimuli',choices:['Flooding therapy','Systematic desensitization','Aversive conditioning','Contingency management'],ans:1,exp:'**Systematic desensitization** (Wolpe) is counterconditioning: relaxation is incompatible with anxiety, and exposure proceeds step by step up a fear hierarchy. Flooding instead exposes the person to the most feared stimulus all at once.'},
  {s:'Cognition, Learning & Memory',aamc:'7C',q:'_____ replaces an unwanted response to a stimulus with a desired, incompatible response by pairing the stimulus with something positive',choices:['Extinction','Habituation','Shaping','Counterconditioning'],ans:3,exp:'In **counterconditioning**, a feared dog is paired with treats so that pleasure replaces fear; systematic desensitization is one form. Extinction simply presents the conditioned stimulus without the unconditioned stimulus until the response fades, without training a new response.'},
  {s:'Cognition, Learning & Memory',aamc:'7C',q:'_____ reinforcers are biological; they satisfy needs naturally and do not need to be learned',choices:['Secondary','Generalized','Negative','Primary'],ans:3,exp:'**Primary** reinforcers include food, water, warmth, and sex. Secondary (conditioned) reinforcers such as money gain value through association with primary reinforcers.'},
  {s:'Cognition, Learning & Memory',aamc:'7C',q:'_____ reinforcers are things we have learned to value, often because they can be used to obtain a primary reinforcer',choices:['Secondary','Primary','Unconditioned','Negative'],ans:0,exp:'**Secondary** (conditioned) reinforcers, such as money, grades, or praise, become rewarding through learning. Primary reinforcers, such as food, are rewarding without learning.'},
  {s:'Emotion, Motivation & Stress',aamc:'7C',q:'In a _____, people earn tokens for target behaviors, and the tokens can later be exchanged for other reinforcers',choices:['fixed-ratio schedule','shaping procedure','token economy','contingency contract'],ans:2,exp:'A **token economy** uses tokens as secondary reinforcers and is used in classrooms and inpatient psychiatric units. Shaping instead reinforces successive approximations of a target behavior.'},
  {s:'Emotion, Motivation & Stress',aamc:'7C',q:'_____ is the tendency of an animal to revert to instinctive behaviors that interfere with a conditioned response',choices:['Spontaneous recovery','Extinction burst','Instinctive drift','Stimulus generalization'],ans:2,exp:'In **instinctive drift**, raccoons trained to deposit coins kept "washing" them instead (Breland and Breland), which shows biological limits on operant conditioning. Spontaneous recovery is the return of an extinguished response after a delay.'},
  {s:'Emotion, Motivation & Stress',aamc:'6B',q:'The paradox of choice states that the more choices there are, the _____ satisfied we become with our final choice',choices:['more','equally','permanently more','less'],ans:3,exp:'Schwartz\'s **paradox of choice**: more options increase decision difficulty, regret, and opportunity costs, so satisfaction with the final choice tends to drop (we become **less** satisfied). This runs against the intuitive expectation that more options always help.'},
  {s:'Emotion, Motivation & Stress',aamc:'7A',q:'_____, an aspect of inhibitory control, is the ability to regulate one\'s emotions, thoughts, and behavior in the face of temptations and impulses',choices:['Self-efficacy','Self-monitoring','Self-control','Self-esteem'],ans:2,exp:'**Self-control** (e.g., delay of gratification in Mischel\'s marshmallow study) relies on the prefrontal cortex. Self-efficacy is the belief that one can succeed at a task (Bandura).'},
  {s:'Emotion, Motivation & Stress',aamc:'7A',q:'_____ refers to the idea that self-control draws on a limited pool of mental resources that can be used up, so self-control is impaired after earlier exertion',choices:['Learned helplessness','Burnout','Amotivation','Ego depletion'],ans:3,exp:'**Ego depletion** (Baumeister) says willpower works like a muscle that tires, though large replication attempts have cast doubt on the effect. Learned helplessness is passivity after repeated uncontrollable bad events.'},
  {s:'Personality, Development & Disorders',aamc:'8A',q:'The _____ self is the most basic part of self-concept: the sense of being separate and distinct from others',choices:['categorical','existential','ideal','looking-glass'],ans:1,exp:'Lewis\'s **existential** self emerges first in infancy (around 2 to 3 months) as awareness that one exists apart from others. The categorical self comes later, as children place themselves in categories such as age and gender.'},
  {s:'Personality, Development & Disorders',aamc:'8A',q:'The _____ self is the ability to place oneself into categories such as age, gender, skill, or size',choices:['existential','ideal','categorical','looking-glass'],ans:2,exp:'The **categorical** self develops in toddlerhood, beginning with concrete categories (age, gender) and later including psychological traits. The looking-glass self (Cooley) is a self-image based on how we think others see us.'},
  {s:'Personality, Development & Disorders',aamc:'8A',q:'_____ emphasizes the important contributions that society and culture make to individual development, stressing interaction between developing people and the culture in which they live',choices:['Psychosexual theory','Cognitive-developmental theory','Attachment theory','Sociocultural theory'],ans:3,exp:'Vygotsky\'s **sociocultural theory** emphasizes social interaction, cultural tools such as language, and the zone of proximal development with scaffolding by more skilled others. Piaget\'s cognitive-developmental theory instead emphasizes the child\'s own exploration through universal stages.'},
  {s:'Personality, Development & Disorders',aamc:'8A',q:'The theory of _____ (George Herbert Mead) states that people develop self-images through interactions with other people, so the self is a product of social experience',choices:['psychosexual development','cognitive development','social behaviorism','radical behaviorism'],ans:2,exp:'Mead\'s **social behaviorism** describes the self developing through role taking (preparatory, play, and game stages) and the "I" versus the "me." Skinner\'s radical behaviorism, by contrast, explains behavior purely through reinforcement, without reference to the self.'},
  {s:'Personality, Development & Disorders',aamc:'8A',q:'The looking-glass self theory suggests that our self-concept is influenced by _____',choices:['our objective accomplishments','how we perceive that others are viewing us','our innate temperament','comparison with a single ideal self'],ans:1,exp:'Cooley\'s **looking-glass self**: we imagine how we appear to others, imagine their judgment, and develop feelings about ourselves from it. Note that it depends on perceived, not actual, evaluations.'},
  {s:'Social Psychology & Society',aamc:'8B',q:'The _____ states that three types of information influence our causal attributions: consensus, distinctiveness, and consistency',choices:['correspondent inference theory','self-perception theory','covariation model','fundamental attribution error'],ans:2,exp:'Kelley\'s **covariation model**: high consensus, high distinctiveness, and high consistency point to a situational (external) cause; low consensus and low distinctiveness with high consistency point to a dispositional (internal) cause. The fundamental attribution error is a bias, not a model of attribution.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ cultures emphasize the needs and goals of the group as a whole over the needs and desires of each individual',choices:['Individualistic','Collectivistic','Ethnocentric','Xenocentric'],ans:1,exp:'**Collectivistic** cultures (common in East Asia) define the self interdependently and show a weaker fundamental attribution error. Individualistic cultures (e.g., the U.S.) prioritize personal goals and independence.'},
  {s:'Cognition, Learning & Memory',aamc:'8B',q:'_____ is the belief that bad things are more likely to happen to others than to ourselves',choices:['Self-serving bias','Actor-observer bias','Hindsight bias','Optimism bias'],ans:3,exp:'**Optimism bias** (e.g., "I won\'t get lung cancer from smoking") undermines health behavior change. Self-serving bias is attributing successes to ourselves and failures to external factors.'},
  {s:'Social Psychology & Society',aamc:'8C',q:'The _____ states that aggression results from blocking, or frustrating, a person\'s efforts to attain a goal',choices:['catharsis hypothesis','frustration-aggression hypothesis','social learning theory','instinct theory'],ans:1,exp:'The **frustration-aggression hypothesis** (Dollard; revised by Berkowitz) says frustration creates a readiness for aggression, especially when aggressive cues are present. Social learning theory instead says aggression is learned by observing models (Bandura\'s Bobo doll study).'},
  {s:'Social Psychology & Society',aamc:'8B',q:'_____ is the practice of singling out a person or group for unmerited blame and the negative treatment that follows',choices:['Stereotyping','Scapegoating','Stigmatization','Tokenism'],ans:1,exp:'**Scapegoating** often involves displacing frustration onto a less powerful minority group during hard times. Stereotyping is a cognitive generalization about a group, not necessarily blame.'},
  {s:'Social Psychology & Society',aamc:'8B',q:'The _____ phenomenon is the tendency to believe that the world is fair and that people get what they deserve',choices:['halo','bystander','just-world','spotlight'],ans:2,exp:'The **just-world** phenomenon leads to victim blaming (e.g., assuming a poor person must be lazy). The spotlight effect is overestimating how much others notice us.'},
  {s:'Social Psychology & Society',aamc:'8B',q:'The _____ is a cognitive bias in which a positive overall impression of a person (e.g., attractiveness) influences judgments of their other traits and character',choices:['false consensus effect','mere-exposure effect','spotlight effect','halo effect'],ans:3,exp:'Through the **halo effect**, attractive people are judged to be smarter and kinder. The mere-exposure effect is liking something more simply because it is familiar.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ is the systematic study of people and cultures, typically through immersion and participant observation from the members\' own point of view',choices:['Demography','Ethnography','Ethnocentrism','Epidemiology'],ans:1,exp:'**Ethnography** is a qualitative method that produces rich description but has limited generalizability and a risk of observer bias. Demography is the quantitative study of population statistics.'},
  {s:'Social Psychology & Society',aamc:'8B',q:'_____ is the preference for the products, styles, or ideas of another culture rather than one\'s own',choices:['Ethnocentrism','Cultural relativism','Cultural imperialism','Xenocentrism'],ans:3,exp:'**Xenocentrism** (xeno = foreign) is the opposite of ethnocentrism, which judges other cultures by one\'s own standards. Cultural relativism is judging a culture by its own standards.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ is the deliberate imposition of one\'s own cultural values on another culture',choices:['Cultural diffusion','Assimilation','Xenocentrism','Cultural imperialism'],ans:3,exp:'**Cultural imperialism** spreads a dominant culture through power (e.g., colonial education policies). Cultural diffusion is the voluntary, often unplanned spread of cultural elements.'},
  {s:'Social Psychology & Society',aamc:'8C',q:'The _____ is a phenomenon in which people tend to develop a preference for things merely because they are familiar with them',choices:['halo effect','false consensus effect','mere-exposure effect','spotlight effect'],ans:2,exp:'The **mere-exposure effect** (Zajonc) explains why songs grow on us and why proximity fosters attraction. The halo effect is one positive trait coloring overall judgments of a person.'},
  {s:'Social Psychology & Society',aamc:'8B',q:'The _____ occurs when we overestimate how many other people share our opinions, beliefs, and behaviors',choices:['pluralistic ignorance effect','spotlight effect','halo effect','false consensus effect'],ans:3,exp:'The **false consensus effect** leads people to see their own choices as common and "normal." Pluralistic ignorance is the opposite error: privately rejecting a norm while wrongly assuming that most others accept it.'},
  {s:'Social Psychology & Society',aamc:'8B',q:'A _____ is the tendency to assume that others (and our future selves) share our current preferences, beliefs, and states',choices:['self-serving bias','projection bias','actor-observer bias','optimism bias'],ans:1,exp:'**Projection bias** includes grocery shopping while hungry and buying for a future that will not feel the same way; it closely parallels the false consensus effect. Actor-observer bias is attributing our own behavior to situations but others\' behavior to their dispositions.'},
  {s:'Social Psychology & Society',aamc:'8C',q:'A _____ is a sequence of behaviors, actions, and consequences that is expected in a particular situation or environment',choices:['social norm','social role','social script','folkway'],ans:2,exp:'A **social script** is an event schema, such as the expected sequence at a restaurant (be seated, order, eat, pay). A social role is the set of expectations attached to a status, such as the role of a physician.'},
  {s:'Social Psychology & Society',aamc:'8C',q:'_____ is the evolutionary strategy that favors the reproductive success of an animal\'s relatives, even at a cost to the animal\'s own survival',choices:['Reciprocal altruism','Sexual selection','Kin selection','Group selection'],ans:2,exp:'**Kin selection** increases inclusive fitness, and Hamilton\'s rule (rB > C) predicts helping when relatedness times benefit exceeds the cost. Reciprocal altruism explains helping non-relatives who are likely to return the favor.'},
  {s:'Social Psychology & Society',aamc:'8C',q:'Altruism among non-relatives that is based on the expectation that the favor will be returned in the future is called _____ altruism',choices:['kin-selected','reciprocal','pure','parental'],ans:1,exp:'**Reciprocal** altruism (Trivers) requires repeated interactions and the ability to recognize and punish cheaters ("I scratch your back, you scratch mine"). Kin selection explains altruism toward relatives instead.'},
  {s:'Social Psychology & Society',aamc:'8C',q:'_____ says that, although costly, altruistic acts may benefit the altruist indirectly by establishing a reputation that signals good qualities to others',choices:['Kin selection theory','Reciprocal altruism theory','Costly signaling theory','Inclusive fitness theory'],ans:2,exp:'In **costly signaling theory**, a costly act is an honest signal of resources or quality (e.g., public generosity), which can raise status and mate value. Reciprocal altruism instead expects a direct return from the person helped.'},
  {s:'Social Psychology & Society',aamc:'8C',q:'_____ is the type of social support that gives someone a sense of social belonging',choices:['Emotional support','Informational support','Tangible support','Companionship support'],ans:3,exp:'**Companionship support** comes from shared activities and belonging (e.g., a running group). Emotional support is empathy and caring, and tangible support is concrete aid such as money or rides.'},
  {s:'Social Psychology & Society',aamc:'8C',q:'_____ refers to unjust and discriminatory treatment of an individual or group by society and its institutions as a whole, rather than by individuals',choices:['Individual discrimination','Prejudice','Stereotype threat','Institutional discrimination'],ans:3,exp:'**Institutional discrimination** is embedded in policies and practices (e.g., redlining) and can persist without individual prejudice. Prejudice is an attitude; discrimination is behavior.'},
  {s:'Social Psychology & Society',aamc:'8C',q:'_____ occurs when a neutral-seeming rule or practice in one institution produces unequal outcomes because it is linked to discriminatory practices in another institution',choices:['Past-in-present discrimination','Side-effect discrimination','Individual discrimination','Intentional institutional discrimination'],ans:1,exp:'In **side-effect discrimination**, a neutral-seeming practice has a discriminatory impact through links between institutions (e.g., a hiring policy based on criminal records reflects bias in policing). Past-in-present discrimination is a neutral practice that perpetuates the effects of earlier intentional discrimination.'},
  {s:'Social Psychology & Society',aamc:'8C',q:'_____ occurs when practices that are neutral today perpetuate the effects of discrimination from the past',choices:['Side-effect discrimination','Individual discrimination','Past-in-present discrimination','Intentional institutional discrimination'],ans:2,exp:'In **past-in-present discrimination**, a seniority-based layoff policy, for example, disadvantages groups that were previously barred from being hired. Side-effect discrimination is instead an unintended spillover from bias in a different institution.'},
  {s:'Social Psychology & Society',aamc:'8C',q:'A _____, also known as a remunerative organization, is one that people join in order to receive a salary or some other tangible benefit offered to members',choices:['normative organization','coercive organization','utilitarian organization','primary group'],ans:2,exp:'In Etzioni\'s typology, a **utilitarian organization** is joined for material reward (e.g., a job or college). Normative organizations are joined voluntarily for shared values, and coercive organizations (prisons) involve involuntary membership.'},
  {s:'Social Psychology & Society',aamc:'8C',q:'_____ have voluntary membership based on shared goals, values, and interests',choices:['Utilitarian organizations','Normative organizations','Coercive organizations','Bureaucracies'],ans:1,exp:'**Normative organizations** (voluntary associations such as charities, clubs, or Mothers Against Drunk Driving) reward members morally rather than materially. Utilitarian organizations are joined for pay or other tangible benefits.'},
  {s:'Social Psychology & Society',aamc:'8C',q:'A prison is an example of a _____, which members do not join voluntarily and which maintains control through force',choices:['utilitarian organization','normative organization','coercive organization','bureaucracy'],ans:2,exp:'**Coercive organizations** (prisons, involuntary psychiatric hospitals) resemble Goffman\'s total institutions. A bureaucracy is Weber\'s rational organizational form, with a hierarchy, written rules, and a division of labor.'},
  {s:'Social Psychology & Society',aamc:'8C',q:'_____ is the process by which society and its institutions take on the characteristics of fast-food restaurants: efficiency, calculability, predictability, and control',choices:['Globalization','Urbanization','Bureaucratization','McDonaldization'],ans:3,exp:'Ritzer\'s **McDonaldization** extends Weber\'s idea of rationalization; its downside is the "irrationality of rationality" (e.g., dehumanizing service). Bureaucratization is the broader spread of formal rules and hierarchy.'},
  {s:'Social Psychology & Society',aamc:'8C',q:'_____ is communication to oneself, such as diaries, self-reminders, or rehearsing what to say',choices:['Metacommunication','Mass communication','Interpersonal communication','Autocommunication'],ans:3,exp:'**Autocommunication** (Lotman) is a message sent to oneself, which can reshape one\'s own identity. Metacommunication is communication about communication, such as tone or body language that frames a message.'},
  {s:'Social Psychology & Society',aamc:'8B',q:'_____ is the attribution of human traits, emotions, or intentions to non-human entities',choices:['Objectification','Anthropomorphism','Dehumanization','Zoomorphism'],ans:1,exp:'**Anthropomorphism** (anthropos = human) is attributing human qualities to non-human things, such as saying a car "hates" cold mornings. Objectification is the reverse: treating a person as a thing.'},
  {s:'Social Psychology & Society',aamc:'8C',q:'_____ describes an ideal situation in which every individual of one sex is an equally likely partner for every member of the opposite sex',choices:['Assortative mating','Disassortative mating','Inbreeding','Random mating'],ans:3,exp:'**Random mating** is one of the Hardy-Weinberg equilibrium assumptions. Real human mating is usually assortative (similar partners pair up), which violates this assumption.'},
  {s:'Social Psychology & Society',aamc:'8C',q:'_____ occurs when individuals with similar phenotypes mate with one another more often than would be expected under random mating',choices:['Random mating','Disassortative mating','Outbreeding','Assortative mating'],ans:3,exp:'Positive **assortative mating** (e.g., by height, education, or religion) increases homozygosity for the traits involved and can reinforce social stratification. Disassortative mating is pairing with dissimilar partners.'},
  {s:'Social Psychology & Society',aamc:'8C',q:'_____ applies game theory to evolving populations, modeling Darwinian competition in terms of contests, strategies, and payoffs',choices:['Kin selection theory','Rational choice theory','Social exchange theory','Evolutionary game theory'],ans:3,exp:'**Evolutionary game theory** (Maynard Smith) introduced evolutionarily stable strategies, such as the hawk-dove game, and explains how cooperation (e.g., tit-for-tat) can evolve. Rational choice theory assumes conscious cost-benefit calculation by individuals.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ refers to the unwritten, unofficial, and often unintended lessons, values, and perspectives that students learn in school',choices:['Teacher expectancy','Tracking','Educational segregation','Hidden curriculum'],ans:3,exp:'The **hidden curriculum** includes lessons such as punctuality and obedience to authority, which conflict theorists see as preparing students for class positions. Teacher expectancy is the self-fulfilling prophecy in which students perform to teachers\' expectations.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ is the weakening of the social and political power of religious organizations as religious involvement declines',choices:['Fundamentalism','Religious pluralism','Secularization','Cultural lag'],ans:2,exp:'**Secularization** is associated with modernization, science, and rationalization (Weber). Fundamentalism is a reaction against it, insisting on strict, literal adherence to traditional beliefs.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ is a reaction to secularization in which members of a religion adopt strict, literal adherence to traditional religious beliefs',choices:['Secularization','Ecumenism','Religious pluralism','Fundamentalism'],ans:3,exp:'**Fundamentalism** often rejects modern secular values. Ecumenism is the opposite trend: different religious groups cooperating and seeking unity.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'A _____ is a form of government in which power is vested in the people and exercised directly by them or by their elected agents under a free electoral system',choices:['monarchy','dictatorship','democracy','theocracy'],ans:2,exp:'A **democracy** may be direct (citizens vote on laws) or representative (citizens elect officials). A theocracy is government by religious authority.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'A _____ is an authoritarian form of government in which a single leader or small group holds power, with little political pluralism or accountability to the people',choices:['democracy','theocracy','constitutional monarchy','dictatorship'],ans:3,exp:'A **dictatorship** concentrates power without free elections or meaningful checks on authority. A constitutional monarchy keeps a monarch as head of state but limits the monarch\'s power through a constitution and elected government.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ is a political and economic system, theorized by Marx, in which classes are abolished, all property is communally owned, and goods are distributed "from each according to ability, to each according to need"',choices:['Socialism','Capitalism','Communism','Feudalism'],ans:2,exp:'**Communism** is Marx\'s final, classless stage, reached after a proletarian revolution against capitalism. In socialism, the means of production are collectively owned, but goods are distributed according to each person\'s contribution.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'A _____ is rule by a king, queen, or emperor, usually through hereditary succession',choices:['oligarchy','theocracy','dictatorship','monarchy'],ans:3,exp:'A **monarchy** may be absolute or constitutional (e.g., the United Kingdom). An oligarchy is rule by a small elite group.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ is an economic system based on the private ownership of the means of production and their operation for profit',choices:['Socialism','Communism','Feudalism','Capitalism'],ans:3,exp:'**Capitalism** relies on markets, competition, and private property; Marx saw it as dividing society into the bourgeoisie and the proletariat. Socialism instead places the means of production under collective ownership.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ is an economic and political system in which the means of production (factories, offices, etc.) are owned collectively by workers or the community rather than by private owners',choices:['Capitalism','Socialism','Feudalism','Mercantilism'],ans:1,exp:'In **socialism**, the value produced belongs to those who produce it, and the state or worker cooperatives often manage production. Capitalism is the opposite: private ownership of production for profit.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ is the process by which human conditions and problems come to be defined and treated as medical conditions, and thus become subjects of medical study, diagnosis, prevention, or treatment',choices:['Demedicalization','Stigmatization','Medicalization','Deinstitutionalization'],ans:2,exp:'**Medicalization** has occurred with ADHD, menopause, and alcoholism, for example. Demedicalization is the reverse, such as the removal of homosexuality from the DSM in 1973.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ is the set of activities that people who consider themselves ill undertake in order to get well',choices:['Health behavior','Illness behavior','Malingering','Sick-role behavior'],ans:3,exp:'In Kasl and Cobb\'s categories, **sick-role behavior** is acting to recover (e.g., taking medication, resting), health behavior is prevention while well, and illness behavior is seeking a diagnosis when symptoms appear. Parsons\'s sick role exempts the ill from normal duties as long as they try to get well.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ is a branch of epidemiology that focuses on the effects of social-structural factors on health',choices:['Clinical epidemiology','Molecular epidemiology','Demography','Social epidemiology'],ans:3,exp:'**Social epidemiology** studies the social determinants of health, such as socioeconomic status, race, and neighborhood (e.g., the gradient in which lower SES predicts worse health). Demography studies population size and composition, not health outcomes specifically.'},
  {s:'Social Psychology & Society',aamc:'10A',q:'In Marxist conflict theory, the _____ is the capitalist class that owns the means of production',choices:['proletariat','petite bourgeoisie','lumpenproletariat','bourgeoisie'],ans:3,exp:'Marx divided capitalist society into the **bourgeoisie** (owners of capital and the means of production) and the proletariat (workers who sell their labor for wages). In everyday speech "bourgeois" can mean middle class, but the MCAT uses the Marxist meaning.'},
  {s:'Social Psychology & Society',aamc:'10A',q:'In Marxist theory, the _____ is the working class: people who do not own the means of production and must sell their labor for wages',choices:['bourgeoisie','petite bourgeoisie','proletariat','aristocracy'],ans:2,exp:'Marx predicted that the **proletariat** would develop class consciousness and overthrow the bourgeoisie. The petite bourgeoisie (e.g., small shopkeepers) owns small amounts of capital but also works.'},
  {s:'Social Psychology & Society',aamc:'8B',q:'In social philosophy, _____ is the act of treating a person, or sometimes an animal, as an object or a thing',choices:['anthropomorphism','objectification','stigmatization','reification'],ans:1,exp:'**Objectification** (e.g., sexual objectification) reduces a person to a body or a tool. Reification is a different error: treating an abstract concept (e.g., "the market") as though it were a concrete thing.'},
  {s:'Social Psychology & Society',aamc:'9B',q:'_____ is a social system in which men hold primary power and predominate in political leadership, moral authority, social privilege, and control of property',choices:['Matriarchy','Oligarchy','Patriarchy','Gerontocracy'],ans:2,exp:'**Patriarchy** (rule by fathers) is a central concept in feminist theory. Gerontocracy is rule by the elderly, and oligarchy is rule by a small elite.'},
  {s:'Social Psychology & Society',aamc:'9B',q:'_____ are people born between about 1946 and 1964, during the post-World War II birth spike',choices:['Generation X','Millennials','Generation Z','Baby boomers'],ans:3,exp:'**Baby boomers** form a large cohort whose aging drives rising Medicare and healthcare demand. Generation X follows them (about 1965 to 1980), then Millennials (about 1981 to 1996).'},
  {s:'Social Psychology & Society',aamc:'9B',q:'_____ is a multidisciplinary approach to mental, physical, and social health that views health as a trajectory shaped by experiences and transitions across the entire lifespan',choices:['Disengagement theory','Activity theory','Life course theory','Continuity theory'],ans:2,exp:'**Life course theory** emphasizes timing, cohort effects, and cumulative advantage or disadvantage (e.g., childhood poverty affecting adult health). Disengagement, activity, and continuity theories address aging specifically.'},
  {s:'Social Psychology & Society',aamc:'9B',q:'_____ refers to the hierarchical ranking of people into age groups within a society, or a system of inequalities linked to age',choices:['Ageism','Age stratification','Age cohort effect','Gerontocracy'],ans:1,exp:'**Age stratification** theory (Riley) examines how age groups receive unequal roles, resources, and status. Ageism is prejudice or discrimination based on age, an attitude rather than a structural system.'},
  {s:'Social Psychology & Society',aamc:'9B',q:'A _____ accepts many different kinds of people, of different races, sexual orientations, cultures, and religions, who keep their distinct identities while coexisting',choices:['homogeneous society','pluralistic society','caste society','assimilationist society'],ans:1,exp:'A **pluralistic society** (the "salad bowl") lets groups keep their distinct cultures. An assimilationist society (the "melting pot") expects minorities to adopt the dominant culture.'},
  {s:'Social Psychology & Society',aamc:'9B',q:'A person who is _____ has a gender identity that shifts over time rather than remaining fixed as a single gender',choices:['cisgender','transgender','agender','gender fluid'],ans:3,exp:'A **gender fluid** person\'s identity moves between or among genders over time. Agender describes having no gender identity, and cisgender describes an identity that matches the sex assigned at birth.'},
  {s:'Social Psychology & Society',aamc:'9B',q:'_____, also known as genderqueer, describes a spectrum of gender identities that are not exclusively masculine or feminine and lie outside the gender binary',choices:['Cisgender','Intersex','Non-binary','Androgynous'],ans:2,exp:'**Non-binary** is a gender identity. Intersex refers to biological sex characteristics that differ from typical male or female patterns, and androgyny refers to gender expression rather than identity.'},
  {s:'Social Psychology & Society',aamc:'9B',q:'A _____ is a social role encompassing the behaviors and attitudes generally considered acceptable, appropriate, or desirable for people based on their actual or perceived sex',choices:['gender identity','gender role','gender schema','gender expression'],ans:1,exp:'A **gender role** is a socially defined set of expectations (e.g., that women be nurturing). Gender identity is a person\'s internal sense of their own gender, and gender expression is how they present it outwardly.'},
  {s:'Social Psychology & Society',aamc:'9B',q:'_____ links social structure and stratification to commonly held ideas and assumptions about race and racial categories, viewing race as socially constructed',choices:['Intersectional theory','Assimilation theory','Contact hypothesis','Racial formation theory'],ans:3,exp:'Omi and Winant\'s **racial formation theory** describes how racial categories are created, changed, and destroyed through "racial projects." The contact hypothesis instead proposes that intergroup contact under the right conditions reduces prejudice.'},
  {s:'Social Psychology & Society',aamc:'8A',q:'Gender schema theory proposes that children learn gender roles from their _____',choices:['culture','prenatal hormone exposure','genetic inheritance','innate brain structure'],ans:0,exp:'Bem\'s gender schema theory holds that children learn their **culture**\'s definitions of masculinity and femininity, then organize information and their own behavior around those cultural gender schemas. It is a learning and cognitive account, not a biological one.'},
  {s:'Social Psychology & Society',aamc:'10A',q:'A _____ is a part of a city in which members of a minority group live, typically as a result of social, legal, or economic pressure',choices:['suburb','gentrified district','commune','ghetto'],ans:3,exp:'A **ghetto** results from involuntary segregation and often concentrated poverty (e.g., through redlining). A gentrified district is an urban area where wealthier newcomers displace lower-income residents.'},
  {s:'Social Psychology & Society',aamc:'9B',q:'_____ is the physiological potential to reproduce, such as the maximum number of children a woman could bear',choices:['Fertility','Mortality','Natality','Fecundity'],ans:3,exp:'**Fecundity** is reproductive capacity, whereas fertility is the actual number of children born. Fecundity is always greater than or equal to fertility.'},
  {s:'Social Psychology & Society',aamc:'9B',q:'_____ proposes that people who are socially isolated are especially vulnerable to the appeals of extremist movements',choices:['Relative deprivation theory','Resource mobilization theory','Value-added theory','Mass society theory'],ans:3,exp:'**Mass society theory** links social movement participation to alienation and weak social ties. Resource mobilization theory instead says movements succeed based on their access to resources such as money, organization, and media.'},
  {s:'Social Psychology & Society',aamc:'9A',q:'_____ states that when an event occurs, someone must decide whether and how to pass the information on to others, such as friends, officials, or journalists',choices:['Agenda-setting theory','Cultivation theory','Uses and gratifications theory','Gatekeeping theory'],ans:3,exp:'In **gatekeeping theory** (Lewin), editors and others act as "gates" that filter which information reaches the public. Agenda-setting theory says the media shape which issues people think are important.'},
  {s:'Social Psychology & Society',aamc:'10A',q:'_____ asserts that people are often disadvantaged by multiple, overlapping sources of oppression, such as race, class, gender identity, sexual orientation, and religion',choices:['Feminist theory','Intersectional theory','Conflict theory','Racial formation theory'],ans:1,exp:'**Intersectional theory** (Crenshaw) holds that overlapping identities create unique experiences of disadvantage that are not simply additive (e.g., the experiences of Black women). Feminist theory centers on gender inequality in particular.'},
  {s:'Sensation & Perception',aamc:'6A',q:'In the auditory pathway, signals travel from the cochlea along the vestibulocochlear nerve and through brainstem nuclei to which thalamic relay before reaching the auditory cortex?',choices:['Lateral geniculate nucleus','Medial geniculate nucleus','Ventral posterolateral nucleus','Pulvinar nucleus'],ans:1,exp:'Auditory signals relay through the **medial geniculate nucleus (MGN)** of the thalamus to the primary auditory cortex in the temporal lobe; mnemonic: medial = music, lateral = light. The lateral geniculate nucleus is the visual relay, and the ventral posterolateral nucleus relays touch and pain from the body.',src:'milesdown:1554744981721'},
  {s:'Social Psychology & Society',aamc:'8C',q:'The social position that becomes a person\'s primary identifying characteristic and dominates how others see them is their _____',choices:['status set','role set','master status','social role'],ans:2,exp:'A **master status** (e.g., "doctor", "ex-convict" or a visible disability) overshadows a person\'s other statuses and shapes how others interact with them; it can be achieved or ascribed. A status set is the full collection of statuses a person holds, and a role set is the group of roles attached to a single status.',src:'milesdown:1556392375967'},
  {s:'Sensation & Perception',aamc:'6A',q:'In order, which sequence describes how a cochlear implant delivers sound to the auditory nerve?',choices:['Microphone → speech processor → external transmitter → implanted receiver/stimulator → cochlear electrode array','Microphone → implanted receiver/stimulator → speech processor → external transmitter → cochlear electrode array','Speech processor → microphone → external transmitter → cochlear electrode array → implanted receiver/stimulator','Microphone → external transmitter → cochlear electrode array → speech processor → implanted receiver/stimulator'],ans:0,exp:'The external **microphone** picks up sound, the **speech processor** turns it into a coded signal, and the **transmitter** coil sends that signal through the skin to the implanted **receiver/stimulator**, which drives the **electrode array** in the cochlea to stimulate auditory nerve fibers directly. Because it bypasses damaged hair cells, an implant helps sensorineural (not conductive) hearing loss.',src:'milesdown:1560652128974'},
  {s:'Sensation & Perception',aamc:'6A',q:'In the sensory homunculus, a map of the primary somatosensory cortex, body parts such as the lips and fingertips appear enlarged because they _____',choices:['are the largest parts of the body','have the densest sensory innervation','contain the most skeletal muscle','are mapped by both hemispheres'],ans:1,exp:'The **sensory homunculus** maps the postcentral gyrus of the parietal lobe; the cortical area given to each region is proportional to its density of sensory receptors, not its physical size, so the hands, lips and tongue are huge and the trunk is small. A separate motor homunculus maps the precentral gyrus, where area reflects fine motor control rather than sensation.',src:'milesdown:1560652348202'},
  {s:'Sensation & Perception',aamc:'6A',q:'Nerve fibers are classified as A, B or C fibers. Which fibers conduct signals fastest, and why?',choices:['B fibers, because they are intermediate in diameter and lightly myelinated','C fibers, because they are small in diameter and unmyelinated','A fibers, because they are large in diameter and myelinated','C fibers, because their unmyelinated membrane conducts continuously'],ans:2,exp:'Conduction velocity rises with **axon diameter** (lower internal resistance) and **myelination** (saltatory conduction), so large, myelinated **A fibers** (e.g., Aα motor fibers; the thinner Aδ fibers carry sharp pain) are fastest, B fibers (preganglionic autonomic) are intermediate, and small unmyelinated C fibers (dull, burning pain) are slowest. Continuous conduction along an unmyelinated membrane is slower, not faster, than saltatory conduction.',src:'milesdown:1560656209940'},
  {s:'Sensation & Perception',aamc:'6A',q:'Foliate papillae are located on the _____ of the tongue, and circumvallate papillae are located at the _____',choices:['back / sides','front / back','sides / front','sides / back'],ans:3,exp:'**Fungiform** papillae are scattered over the front (tip) of the tongue, **foliate** papillae form folds along the rear sides, and the large **circumvallate** papillae form a V-shaped row at the back. Filiform papillae, the most numerous, have no taste buds and give the tongue its rough texture.',src:'milesdown:1560721533685'},
  {s:'Biological Bases of Behavior',aamc:'6B',q:'A subcutaneous injection delivers a drug into the _____',choices:['dermis just beneath the epidermis','fatty hypodermis beneath the dermis','skeletal muscle beneath the fat layer','epidermis just above the dermis'],ans:1,exp:'**Subcutaneous** ("under the skin") injections, such as insulin, go into the fatty hypodermis; **intradermal** injections, such as the tuberculin skin test, go into the dermis just below the epidermis; and **intramuscular** injections, such as many vaccines, go deep into skeletal muscle. Because muscle is highly vascular, intramuscular drugs are usually absorbed faster than subcutaneous ones.',src:'milesdown:1560777685565'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is the ability to arrive at the single correct answer to a standard question that requires little creativity, as on most multiple-choice intelligence tests',choices:['Divergent thinking','Lateral thinking','Heuristic thinking','Convergent thinking'],ans:3,exp:'**Convergent thinking** narrows many possibilities down to one best answer and is what standard IQ and school tests reward. **Divergent thinking** is its opposite: generating many varied, creative solutions to an open-ended problem (e.g., listing all the uses for a brick).',src:'milesdown:1560875688272'},
  {s:'Cognition, Learning & Memory',aamc:'6B',q:'_____ is the process of identifying a word and connecting it to its meaning, which is stored in long-term memory',choices:['Lexical access','Semantic priming','Phonological encoding','Morphological parsing'],ans:0,exp:'During **lexical access**, the brain matches a heard or read word form to its entry in the mental lexicon and retrieves its meaning; access is faster for frequent and recently encountered words. Semantic priming is the speeding of that access by a related word presented just before (e.g., "doctor" before "nurse").',src:'milesdown:1560896172204'},
  {s:'Social Psychology & Society',aamc:'9B',q:'A person who does not identify with any gender is described as _____',choices:['gender fluid','agender','bigender','cisgender'],ans:1,exp:'**Agender** people have no gender identity (or a neutral one) and generally fall under the non-binary umbrella. Gender fluid people have an identity that shifts over time, bigender people identify with two genders, and cisgender people identify with the sex they were assigned at birth.',src:'milesdown:1562624294382'},
];
